(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0006.js"] = [{"id":"poem-283c055a06731b4f4bba5eca","title":"叨叨令","author":"无名氏《张协状元》","dynasty":"元","verses":["贫则虽贫，每恁地娇，这两眉儿扫。","有时暗忆妾爹娘，珠泪堕润湿芳容，甚人知道？妾又无人要。","兼自执卓做人，除非是苦怀抱。","妾又无倚靠。","付分缘与人缉麻，夜间独自，宿在古庙。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2459","tags":[]},{"id":"poem-283c9047e57fbbb09c8c44f4","title":"池州夫子庙麟台","author":"韦表微","dynasty":"唐","verses":["二仪既闭，三象乃乖。","圣道埋郁，人心不开。","上无文武，下有定哀。","吁嗟麟兮，孰为来哉。","周虽不纲，孔实嗣圣。","诗书既删，礼乐大定。","劝善惩恶，奸邪乃正。","吁嗟麟兮，克昭符命。","圣与时合，化行位尊。","苟或乖戾，身穷道存。","于昭鲁邑，栖迟孔门。","吁嗟麟兮，孰知其仁。","运极数残，德至时否。","楚国寖广，秦封益侈。","墙仞迫阨，崎岖阙里。","吁嗟麟兮，靡有攸止。","世治则麟，世乱则麕。","出非其时，麋鹿同群。","孔不自圣，麟不自祥。","吁嗟麟兮，天何所亡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e4545449-1757-4265-96bb-8fb65870b953","tags":[]},{"id":"poem-2842081059bf5e072d4c5c2a","title":"次韵刘莘老学士惜别言怀兼呈次中察院二首  其二","author":"苏颂","dynasty":"宋","verses":["诗侣方逢梦与微，摅怀未尽遽言归。","正思玉鲙将登俎，应笑缁尘又染衣。","金石交情知不改，辅车形体自相依。","何时得遂江湖乐，薄宦牵羁甚𬙊徽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-62d60738-77dd-4c0b-b21d-5ce037fed28e","tags":[]},{"id":"poem-284dfc5df573648868b64b9c","title":"式微","author":"佚名","dynasty":"先秦","verses":["式微，式微，胡不归？微君之故，胡为乎中露！","式微，式微，胡不归？微君之躬，胡为乎泥中！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-35","tags":[]},{"id":"poem-284e4ac946fef04aaaabed21","title":"偈颂七十一首  其三四","author":"释了惠","dynasty":"宋","verses":["这些业种自何来，虽不同门共一家。","连累山僧至今日，一重枷上又添枷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-af59cbb0-b17f-4ad1-9ee7-a0f1ced130e8","tags":[]},{"id":"poem-284f19545ad7ddcc94a884c0","title":"句  其五","author":"滕元发","dynasty":"宋","verses":["负鼎早为汤右相，有文今作鲁夫人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-099f35a4-c596-4620-9b64-03d1b0a466e7","tags":[]},{"id":"poem-284fec74e933ceaa6550a501","title":"寒食","author":"韩翃","dynasty":"唐","verses":["春城无处不飞花，寒食东风御柳斜。","日暮汉宫传蜡烛，轻烟散入五侯家。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-77ac62ee-6396-4ac0-a3ab-cb84ba2e5cd0","tags":["唐诗三百首","清明","寒食节","典故","七言绝句","讽刺"]},{"id":"poem-28553f356d1f31966e35e853","title":"鱼丽","author":"佚名","dynasty":"先秦","verses":["鱼丽于罶，鲿鲨。君子有酒，旨且多。","鱼丽于罶，鲂鳢。君子有酒，多且旨。","鱼丽于罶，鰋鲤。君子有酒，旨且有。物其多矣，维其嘉矣！物其旨矣，维其偕矣！物其有矣，维其时矣！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-169","tags":[]},{"id":"poem-2856578d9f745428840652ed","title":"扬之水","author":"佚名","dynasty":"先秦","verses":["扬之水，白石凿凿。素衣朱襮，从子于沃。既见君子，云何不乐？","扬之水，白石皓皓。素衣朱绣，从子于鹄。既见君子，云何其忧？","扬之水，白石粼粼。我闻有命，不敢以告人。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-115","tags":[]},{"id":"poem-2858849b281ae4a481cbf86b","title":"阮郎归·留连春意晚花稠","author":"赵","dynasty":"宋","verses":["留连春意晚花稠。","云疏雨未收。","新荷池面叶齐抽。","凉天醉碧楼。","能达理，有何愁。","心宽万事休。","人生还似水中沤。","金尊尽更酬。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-290","tags":[]},{"id":"poem-285ad33c371d3bf3e3c519a8","title":"送韦秀才","author":"皎然","dynasty":"唐","verses":["晨装行堕叶，万里望桑干。","旧说泾关险，犹闻易水寒。","黄云战后积，白草暮来看。","近得君苗信，时教旅思宽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-58425418-7cca-4d94-959e-0a9fdff1b95a","tags":[]},{"id":"poem-285b6497ed5f7d01973ac01b","title":"郡圃有荔支名白蜜者熟最晚戏成一绝","author":"王十朋","dynasty":"宋","verses":["纷纷蜂采百花归，蜜在枝头竟不知。","造物要令甜在后，时人莫讶熟何迟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b8f8f1c2-0c6e-4d69-8ffa-aab15d88dd00","tags":[]},{"id":"poem-285e981e55105bd9015753ae","title":"小园","author":"吕从庆","dynasty":"唐","verses":["小园春色丽，花发两三株。","露笋抽泥立，风兰狎石铺。","教儿棋正歇，得客酒重沽。","意绪浑如此，诗肠老未枯。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0819a70f-825d-42ac-bc09-018ba13ddc1c","tags":[]},{"id":"poem-286140a71f1316ca402bbf21","title":"思帝乡·如何","author":"孙光宪","dynasty":"五代","verses":["如何？遣情情更多。","永日水堂帘下，敛羞蛾。","六幅罗裙窣地，微行曳碧波。","看尽满地疏雨，打团荷。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-35","tags":[]},{"id":"poem-286460e5cd39f2072e20deb7","title":"谒金门·溪声咽","author":"蔡伸","dynasty":"宋","verses":["溪声咽。","溪上有人离别。","别语叮咛和泪说。","罗巾沾泪血。","尽做刚肠如铁。","到此也应愁绝。","回首断山帆影灭。","画船空载月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-992","tags":[]},{"id":"poem-286639f29413a2abaa342b67","title":"拟寒山 八","author":"泰钦","dynasty":"唐","verses":["野老负薪归，催妇连宵织。","看他家事忙，且道承谁力。","问渠渠不知，特地生疑惑。","伤嗟今古人，几个知恩德。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0c73ce34-9710-4ef4-a11a-b9bb8313a5ab","tags":[]},{"id":"poem-28688423b4ba4b901a2c98d3","title":"下杜城","author":"罗隐","dynasty":"唐","verses":["来往城南十八年，赖家桥上潏河边。","村醪香美脱衣典，几度落花相对眠。","（《类编长安志》卷九。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f90aa5c2-14f4-4aad-8642-66cfad89975d","tags":[]},{"id":"poem-286bc77e0130b81068af54e1","title":"初春小雨","author":"韩愈","dynasty":"宋","verses":["天街小雨润如酥，草色遥看近却无。","最是一年春好处，绝胜烟柳满皇都。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-初春小雨","tags":[]},{"id":"poem-28753fb8ad2deb4d055e2676","title":"浣溪沙·欲寄愁心朔雁边","author":"纳兰性德","dynasty":"清","verses":["欲寄愁心朔雁边，西风浊酒惨离颜。","黄花时节碧云天。","古戍烽烟迷斥堠，夕阳村落解鞍鞯。","不知征战几人还。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-132","tags":[]},{"id":"poem-288d3278ffe23ad6240c677e","title":"颂古七十六首  其一二","author":"释士珪","dynasty":"宋","verses":["胡乱三十年，不曾少盐酱。","江西马大师，南岳让和尚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-338e5ff7-ee81-42c0-a7e2-8115d1533032","tags":["衡山"]},{"id":"poem-288f449c8bb394bd33e6b97b","title":"句","author":"李贻孙","dynasty":"唐","verses":["群乌幸胙余。","（见宋陆游《入蜀记》卷六。","）（〖1〗《入蜀记》卷六页十一〖《知不足斋丛书》本〗：「祠旧有乌数百，送迎客舟。","自唐夔州刺史李贻孙诗已云群乌幸胙余矣。","」〖2〗李贻孙，原作李贻。","李贻孙曾官夔州刺史，《全唐文》卷五四四收其会昌五年撰《夔州都督府记》，《金石录》卷九著录会昌五年九月「唐李贻孙《神女庙诗》」。","陆游在述巫山神女祠中景物时引及此句，应即《神女庙诗》之残句。","）（两《唐书》无李贻孙传，今参张忱石所考，补传如次：李贻孙，字里不详。","大和初任福建团练副使，会昌五年为夔州刺史，大中三年任左谏议大夫充宏文馆学士，大中五年任福建观察使。","又曾任金部、司勋员外郎。","约卒于大中六年后。","原列「无考」作者，今移此。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0cf02b7f-f3b8-44b5-8ea0-8574d7f14b6a","tags":[]},{"id":"poem-289008a2147e05364d043c53","title":"如梦令·多谢西池桃李","author":"吕渭老","dynasty":"宋","verses":["多谢西池桃李。","伴我一春沈醉。","能有几多香，陪了一江来泪。","憔悴。","憔悴。","又是落花铺地。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-92","tags":[]},{"id":"poem-2895edf1a28def476d0d61a4","title":"中秋","author":"刘得仁","dynasty":"唐","verses":["尘里兼尘外，咸期此夕明。","一年惟一度，长恐有云生。","露洗微埃尽，光濡是物清。","朗吟看正好，惆怅又西倾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-64f7ffee-d8d2-40c2-96b1-f65bb510bf2b","tags":["抒情","节日","中秋"]},{"id":"poem-28967f9592145b131668d26f","title":"望远行·露滴幽庭落叶时","author":"李珣","dynasty":"五代","verses":["露滴幽庭落叶时，愁聚萧娘柳眉。","玉郎一去负佳期，水云迢递雁书迟。","屏半掩，枕斜欹，蜡泪无言对垂。","吟蛩断续漏频移，入窗明月鉴空帷。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-42","tags":[]},{"id":"poem-28a3c85eed511f39e17dc983","title":"兵要望江南 医方第二十九（十六首） 二","author":"易静","dynasty":"唐","verses":["如瘴气，鹘骨火烧将。","便去上风焚此物，众人闻此灭灾殃，从此得安康。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e11956ec-1a97-43e5-abb7-2e404d2cdb46","tags":[]},{"id":"poem-28a59207e17acf274c06e142","title":"奉和元孚大德（亦依本韵）","author":"王謩","dynasty":"唐","verses":["华顶高峰接太虚，承攀琪树赋垂珠。","当时惟有建公在，老宿如今一半无。","（见明陶宗仪《古刻丛钞》，与元孚诗同刻一石。","）（案诗原署「中散大夫行台州司马赐鱼袋王謩幷书」。","又刻后纪「唐大中九年岁次乙亥八月丁丑朔六日壬午重题，以纪他年之事」，共廿六字。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2c23eb99-403d-4bea-bf4d-f72a14dd9ef4","tags":[]},{"id":"poem-28b1a1442eafd2fedeefe072","title":"句  其一","author":"王秬","dynasty":"宋","verses":["何时五亩成归计，来作邻翁伴艺林。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f413fa5e-98d2-46c9-859a-2a9ffec64975","tags":[]},{"id":"poem-28ba188e7a8ceab221b209a6","title":"唐植甫左司挽词二首  其一","author":"李纲","dynasty":"宋","verses":["践历髙华久，巍然誉望崇。","典章谙故熟，翰墨老弥工。","骾亮传家法，清忠迈古风。","温温江玉砚，同閟九原中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-01bb4984-07ae-479f-822d-7b34b66af0ab","tags":[]},{"id":"poem-28becf9582cd32ade82c80ad","title":"菩萨蛮·佳人学得平阳曲","author":"张先","dynasty":"宋","verses":["佳人学得平阳曲。","纤纤玉笋横孤竹。","一弄入云声。","海门江月清。","髻摇金钿落。","惜恐樱唇薄。","听罢已依依。","莫吹杨柳枝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-379","tags":[]},{"id":"poem-28c085350344bee4f0212dc2","title":"又一首","author":"张𬸦","dynasty":"唐","verses":["梦中疑是实，觉后忽非真。","诚知肠欲继，穷鬼故调人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7e3f42c0-6165-4212-88a2-f0bca754e1be","tags":[]},{"id":"poem-28c0f4c3157baac5a4ced8a1","title":"望远村","author":"皎然","dynasty":"唐","verses":["林杪不可分，水步遥难辨。","一片山翠边，依稀见村远。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-58c91a06-3e08-4d81-892e-7ae8afc5f409","tags":[]},{"id":"poem-28c5a8d24095e673b90f21ef","title":"浣溪沙·天碧罗衣拂地垂","author":"欧阳炯","dynasty":"五代","verses":["天碧罗衣拂地垂，美人初着更相宜，宛风如舞透香肌。","独坐含颦吹风竹，园中缓步折花枝，有情无力泥人时。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-45","tags":[]},{"id":"poem-28d0ccb575b2400aaf6800a4","title":"西江月·名与牡丹联谱","author":"康与之","dynasty":"宋","verses":["名与牡丹联谱，南珍独比江瑶。","闽山入贡冠前朝。","露叶风枝袅袅。","香玉满苞仙液，绉红圆戚鲛绡。","华清宫殿蜀山遥。","一骑红尘失笑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-289","tags":[]},{"id":"poem-28d87ec4b41875355fc24f96","title":"奉同颜使君真卿开元寺经藏院会观树文殊碑","author":"皎然","dynasty":"唐","verses":["万国布殊私，千年降祖师。","雁门传法至，龙藏立言时。","故实刊周典，新声播鲁诗。","六铢那更拂，劫石尽无期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4ea14494-6cc2-4c8e-93c5-e1e83816dddc","tags":[]},{"id":"poem-28dd28a7870f0afd044d0d7f","title":"春暮思平泉杂咏二十首 月桂","author":"李德裕","dynasty":"唐","verses":["何年霜夜月，桂子落寒山。","翠干生岩下，金英在世间。","幽崖空自老，清汉未知还。","惟有凉秋夜，嫦娥来暂攀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-805f3344-6463-490d-9751-736ceb7b0d35","tags":[]},{"id":"poem-28e5babbdf2769ad97749df9","title":"一络索·野火拂云微绿","author":"纳兰性德","dynasty":"清","verses":["野火拂云微绿，西风夜哭。","苍茫雁翅列秋空，忆写向、屏山曲。","山海几经翻覆，女墙斜矗。","看来费尽祖龙心，毕竟为、谁家筑。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-64","tags":[]},{"id":"poem-28e99ad689193ba8aa7f471e","title":"苏幕遮·燎沈香","author":"周邦彦","dynasty":"宋","verses":["燎沈香，消溽暑。","鸟雀呼晴，侵晓窥檐语。","叶上初阳干宿雨，水面清圆，一一风荷举。","故乡遥，何日去。","家住吴门，久作长安旅。","五月渔郎相忆否。","小楫轻舟，梦入芙蓉浦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-396","tags":[]},{"id":"poem-290b58df38f2f40bd171c15e","title":"闻砧","author":"裴说","dynasty":"唐","verses":["深闺乍冷鉴开箧，玉筯微微湿红颊。","一阵霜风杀柳条，浓烟半夜成黄叶。","垂垂白练明如雪，独下闲堦转凄切。","祗知抱杵捣秋砧，不觉高楼已无月。","时闻寒雁声相唤，纱窓只有灯相伴。","几展齐纨又嬾裁，离肠恐逐金刀断。","细想仪形执牙尺，回刀剪破澄江色。","愁捻银针信手缝，惆怅无人试宽窄。","时时举袖匀红泪，红牋谩有千行字。","书中不尽心中事，一片慇懃寄边使。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-04517228-74f6-41af-bcba-9bda057ed296","tags":[]},{"id":"poem-2910854cd592e5aa469c8a6e","title":"趋翰苑遭诬搆四十六韵","author":"李绅","dynasty":"唐","verses":["九五当干德，三千应瑞符。","纂尧昌圣历，宗禹盛丕图。","画象垂新令，消兵易旧谟。","选贤方去智，招谏忽升愚。","大乐调元气，神功运化罏。","脱鳞超沆瀣，翻翼集蓬壶。","捧日恩光别，抽毫顾问殊。","凤形怜彩笔，龙颔借骊珠。","掷地声名寡，摩天羽翮孤。","洁身酬雨露，利口扇谗谀。","碧海同宸眷，鸿毛比贱躯。","辨疑分黑白，举直觝朋徒。","庭兽方呈角，阶蓂始効莩。","日倾乌掩魄，星落斗摧枢。","坠劒悲乔岳，号弓泣鼎湖。","乱群逢害马，择肉纵狂䝙。","胆为隳肝竭，心因沥血枯。","满帆摧骇浪，征棹折危途。","燕客书方诈，尧门信未孚。","谤兴金就铄，毁极玉生瘉。","砺吻矜先搏，张罗骋疾驱。","地嫌稀魍魉，海恨止番禺。","瘴岭冲蛇入，蒸池蹑虺趋。","望天收雪涕，看镜揽霜须。","草毒人惊剪，茅荒室未诛。","火风晴处扇，山鬼雨中呼。","穷老乡关远，羇愁骨肉无。","鹊灵窥牖户，龟瑞出泥途。","烟岛深千瘴，沧波淼四隅。","海标传信使，江棹认妻孥。","到接三冬暮，来经六月徂。","暗滩朝不怒，惊濑夜无虞。","俛首安羸业，齐眉慰病夫。","涸鱼思雨润，僵燕望雷苏。","诏下因颁朔，恩移讵省辜。","诳天犹指鹿，依社尚凭狐。","度岭瞻牛斗，浮江淬辘轳。","未平人睚眦，谁惧鬼揶揄。","盆浦潮通楚，匡山地接吴。","庾楼清桂满，远寺素莲敷。","髣髴皆停马，悲欢尽隙驹。","旧交封宿草，衰鬓重生刍。","万戟分梁苑，双旌寄鲁儒。","骎骎移岁月，冉冉近桑榆。","疲马愁千里，孤鸿念五湖。","终当赋归去，那更学杨朱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-bd879428-876f-438d-a803-e7d4012a15d3","tags":["庐山"]},{"id":"poem-29139cfa1331ddf42680136a","title":"春秋战国门 乐羊","author":"周昙","dynasty":"唐","verses":["桮羹忍啜得非忠，巧佞胡为惑主聪。","盈箧谤书能寝默，中山不是乐羊功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-65bc738e-d53f-4baa-9024-714ce6a25c02","tags":[]},{"id":"poem-292f596c4a2ec219091fb162","title":"谒寇忠愍祠堂六首  其二","author":"李纲","dynasty":"宋","verses":["一幸江南一蜀中，奋然廷议叱群公。","搀回天步虽良策，元是真皇听纳功。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d03c7a03-cb4e-47e6-b04d-456d1ef07a91","tags":[]},{"id":"poem-292fd39199336c51e64d4a1d","title":"观沧海","author":"曹操","dynasty":"汉","verses":["东临碣石，以观沧海。","水何澹澹，山岛竦峙。","树木丛生，百草丰茂。","秋风萧瑟，洪波涌起。","日月之行，若出其中；星汉灿烂，若出其里。","幸甚至哉，歌以咏志。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-4","tags":[]},{"id":"poem-293fd88db5638e28e0d5b975","title":"宛转行","author":"张籍","dynasty":"唐","verses":["华屋重翠幄，绮席雕象床。","远漏微更疎，薄衾中夜凉。","炉气暗裴徊，寒灯背斜光。","妍姿结宵态，寝臂幽梦长。","宛转复宛转，忆君更未央。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a002dfd5-85f1-451e-aff2-9971432d0a23","tags":[]},{"id":"poem-2942e93b49b9b7b2e6ce7ba6","title":"隔浦莲・隔浦莲近拍·垂杨烟湿嫩葆","author":"方千里","dynasty":"宋","verses":["垂杨烟湿嫩葆。","别屿环清窈。","绀影浮新涨，夷犹终日鱼鸟，花妥庭下草。","鸣蝉闹。","暗绿藏台沼。","野轩小。","敧眠断梦，闲书风叶颠倒。","诗怀酒思，悔费十年昏晓。","投老红尘倦再到。","愁觉。","悠然心寄天表。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-513","tags":[]},{"id":"poem-294a75f1e0327243fd3d191c","title":"送越僧元瑞","author":"项斯","dynasty":"唐","verses":["静中无伴侣，今亦独随缘。","昨夜离空室，焚香净去船。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f9ff3802-4992-441c-9cff-96cebd964b09","tags":[]},{"id":"poem-294f4e52cb713ff6d0fa8dfa","title":"·","author":"马友鹿","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ea9cef18-11ef-4324-aa73-8fd1e686630c","tags":[]},{"id":"poem-29660db769b54f4a694a9006","title":"蓦山溪·兰台仙史","author":"晁补之","dynasty":"宋","verses":["兰台仙史，好在多情否。","不寄一行书，过西风、飞鸿去后。","功名心事，千载与君同，只狂饮，只狂吟，绿鬓殊非旧。","山歌村馆，愁醉浔阳叟。","且借两州春，看一曲、樽前舞袖。","古来毕竟，何处是功名，不同饮，不同吟，也劝时开口。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-192","tags":[]},{"id":"poem-296e67db51626af83ea3385b","title":"蜀先主庙","author":"刘禹锡","dynasty":"唐","verses":["天地英雄气，千秋尚凛然。","势分三足鼎，业复五铢钱。","得相能开国，生儿不象贤。","凄凉蜀故妓，来舞魏宫前。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2f37297b-77d5-412b-bc73-105bfa4d011d","tags":["唐诗三百首","隋・唐・五代","咏史怀古","五言律诗"]},{"id":"poem-29731f4ce1d82665705a6558","title":"步出夏门行 艳","author":"曹操","dynasty":"汉","verses":["云行雨步，超越九江之皋。","临观异同，心意怀犹豫，不知当复何从？","经过至我碣石，心惆怅我东海。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-21","tags":[]},{"id":"poem-2979d02229ffd092245d9ede","title":"赠来进士鹏","author":"李咸用","dynasty":"唐","verses":["语玄人不到，星汉在灵空。","若使无良遇，虚言有至公。","月明千峤雪，滩急五更风。","此际苦吟力，分将造化功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-7eecbf0f-c2f3-45b8-8626-eba2f3fc57b0","tags":[]},{"id":"poem-297aacdc99333147e0f8eeae","title":"麻婆子","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(丑上)做奴做奴空惆怅，何时得嫁马上郎？做奴做奴空劳攘，只落得一个晓夜忙。","遇冬节，巧梳妆，身穿一套好衣裳。","市人见了都夸奖，道我是个风流好养娘。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8323","tags":[]},{"id":"poem-297e9855c09d082ae5fab3e9","title":"春秋战国门 杨回","author":"周昙","dynasty":"唐","verses":["三逐乡闾五去君，莫知何地可容身。","杨回不是逢英鉴，白首无成一旅人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-13ded6a6-b9c9-4868-ba7f-49f3907962f1","tags":[]},{"id":"poem-297f51ccfc977996825ff662","title":"寄白司马","author":"徐凝","dynasty":"唐","verses":["三条九陌花时节，万户千车看牡丹。","争遣江州白司马，五年风景忆长安。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e0405336-8492-4a9b-a4b0-81ea656a22a8","tags":[]},{"id":"poem-298896b9e0822950fc14070c","title":"幽情","author":"李收","dynasty":"唐","verses":["幽人惜春暮，潭上折芳草。","佳期何时还，欲寄千里道。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d2badd5e-3ef1-45e1-a80c-7a520b185952","tags":[]},{"id":"poem-2999129309e7c173604f62a7","title":"初夏戏题","author":"徐夤","dynasty":"唐","verses":["长养薰风拂晓吹，渐开荷芰落蔷薇。","青虫也学庄周梦，化作南园蛱蝶飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-40b0453a-1856-4853-a9ca-618f7b951f97","tags":[]},{"id":"poem-29a5f7f83f8c3d849abc7b43","title":"题朱中老宣德墓亭","author":"华镇","dynasty":"宋","verses":["不矜乡版早为宾，不叹恩纶晚及身。","物识傥来忘世累，学随所遇泽吾民。","鸿冥轻举闲刀刃，舟壑潜移冷隙尘。","今日户庭皆似旧，共知君有克家人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-94806c90-7a9f-449a-bdf4-8fd70f6cb56f","tags":[]},{"id":"poem-29aa98e7cc03804755b9873c","title":"送灵澈上人","author":"刘长卿","dynasty":"唐","verses":["苍苍竹林寺，杳杳钟声晚。","荷笠带夕阳，青山独归远。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a746d1f0-a72c-44d2-8b1c-c5c990749257","tags":["唐诗三百首","山水","抒情","送别","初中古诗","即景抒情","五言绝句","七年级下册(课外)"]},{"id":"poem-29b0216710ef491e6155aeca","title":"岁暮还家","author":"于邺","dynasty":"唐","verses":["东西流不驻，白日与车轮。","残雪半成水，微风应欲春。","几经他国岁，已减故乡人。","回首长安道，十年空苦辛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bf891f5f-857e-404c-8297-42cfbd109ff2","tags":[]},{"id":"poem-29bbf6a5b6c7c6bcfef4c589","title":"李才翁懒窝  其四","author":"林宪","dynasty":"宋","verses":["山林日月长，城市炎凉急。","方看夏太清，已觉秋淅瑟。","因之念故山，鹤归松露滴。","收足否愿余，此舟徒役役。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-ea3cf54a-5093-4f99-a1c1-2e751c408880","tags":[]},{"id":"poem-29bf8ac0d7459aa187db1308","title":"送王判官","author":"徐安贞","dynasty":"唐","verses":["明月开三峡，花源出五谿。","城池青壁里，烟火绿林西。","不畏王程促，惟愁仙路迷。","巴东下归櫂，莫待夜猨啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0e108e6e-25e0-4682-b0c6-c985af3c67f4","tags":[]},{"id":"poem-29c892c67af2aad09bd4cd84","title":"卜算子慢·溪山别意","author":"张先","dynasty":"宋","verses":["溪山别意，烟树去程，日落采苹春晚。","欲上征鞍，更掩翠帘相眄。","惜弯弯浅黛长长眼。","奈画阁欢游，也学狂花乱絮轻散。","水影横池馆。","对静夜无人，月高云远。","一饷凝思，两袖泪痕还满。","恨私书、又逐东风断。","纵西北层楼万尺，望重城那见。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-313","tags":[]},{"id":"poem-29c8c0ee","title":"咏史·其二","author":"左思","dynasty":"晋","verses":["郁郁涧底松，离离山上苗。","以彼径寸茎，荫此百尺条。","世胄蹑高位，英俊沉下僚。","地势使之然，由来非一朝。","金张藉旧业，七叶珥汉貂。","冯公岂不伟，白首不见招。"],"enabled":true,"collection":"历代名篇","source":"《文选》卷二十一左思《咏史八首》其二。","tags":["咏史"]},{"id":"poem-29d590d28a046625523daa95","title":"永团圆","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["名传四海人怎比？岂独是耀门闾？人生怕不全孝义，圣明世岂相弃。","这隆恩美誉，从教管领何所愧，万古青编记。","如今便去，相随到京畿。","拜谢君恩了，归庭宇，一家贺喜。","共设华筵会，四景常欢聚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5283","tags":[]},{"id":"poem-29df12f8ee5c1317f095cf57","title":"送吴郎西使成州","author":"徐铉","dynasty":"宋","verses":["所向皆为道，遐征岂足辞。","中华垂尽处，别路正秋时。","高阁兰台笔，闲吟板屋诗。","良工无弃物，珍重岁寒姿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-552757cd-4ce6-44b2-aff5-a7af7a856905","tags":[]},{"id":"poem-29ed6a63044e238ac42a219a","title":"绸缪","author":"佚名","dynasty":"先秦","verses":["绸缪束薪，三星在天。今夕何夕，见此良人？子兮子兮，如此良人何？","绸缪束刍，三星在隅。今夕何夕，见此邂逅？子兮子兮，如此邂逅何？","绸缪束楚，三星在户。今夕何夕，见此粲者？子兮子兮，如此粲者何？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-117","tags":[]},{"id":"poem-29f2f0eb6619be077d8856f0","title":"送郎使君赴郢州","author":"司空曙","dynasty":"唐","verses":["使君持节去，云水满前程。","楚寺多连竹，江樯远暎城。","登楼向月望，赛庙傍山行。","若动思乡咏，应贻谢步兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f66d3849-b32b-41d8-8bc0-8845cb0eb7ed","tags":[]},{"id":"poem-29f4905eda199d9f480dc2cd","title":"同二相已下群官乐游园宴","author":"明皇帝","dynasty":"唐","verses":["撰日岩廊暇，需云宴乐初。","万方朝玉帛，千品会簪裾。","地入南山近，城分北斗余。","池塘垂柳密，原隰野花疎。","帟幕看逾暗，歌钟听自虚。","兴阑归骑转，还奏弼违书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4db72c93-5036-478a-8ce9-bf6f87469198","tags":[]},{"id":"poem-2a01db31abdf3910e1e84dd6","title":"到长沙月余即上章复丐宫祠以诗陈情寄吕丞相元直","author":"李纲","dynasty":"宋","verses":["衰病投闲不记年，误恩暂到楚江边。","布宣威德销群盗，循抚疲癃理废田。","报国固将求尺寸，乞身又欲老林泉。","归欤晚节知无悔，赖有元台为保全。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-71b8e58f-ba89-4d28-9405-c33388240be8","tags":[]},{"id":"poem-2a06531ddb3fa2a0dabb4c31","title":"奉和幸韦嗣立山庄侍宴应制","author":"武平一","dynasty":"唐","verses":["三光回斗极，万骑肃钩陈。","地若游汾水，畋疑历渭滨。","圆塘冰写镜，遥树露成春。","弦奏鱼听曲，机忘鸟狎人。","筑岩思感梦，磻石想垂纶。","落景摇红壁，层阴结翠筠。","素风纷可尚，玄泽蔼无垠。","薄暮清笳动，天文焕紫宸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-366d110f-3fb7-463c-b21c-860b7b609941","tags":[]},{"id":"poem-2a12783d731ef1f82491cc6f","title":"减字木兰花·新诗细览","author":"倪偁","dynasty":"宋","verses":["新诗细览。","满纸骊珠光眩眼。","高论倾湖。","倒峡词源世不如。","园池日胜。","只恨孤鸾犹舞镜。","陶写须诗。","怪得连篇字字奇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-467","tags":[]},{"id":"poem-2a131a4bffe251b05df42d9f","title":"晚归","author":"释居简","dynasty":"宋","verses":["晚凉初试出严城，云表浮图恰上灯。","归櫂只知将月去，不知摇碎玉棱棱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-19d12736-f27e-40f4-8d04-7987321d2533","tags":[]},{"id":"poem-2a13ad541321d5e58a1178e8","title":"长安疾后首秋夜即事","author":"卢纶","dynasty":"唐","verses":["九重深锁禁城秋，月过南宫渐映楼。","紫陌夜深槐露滴，碧空云尽火星流。","清风刻漏传三殿，甲第歌钟乐五侯。","楚客病来乡思苦，寂寥灯下不胜愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-87b6f483-98c5-4ec5-a715-87e36110e96b","tags":[]},{"id":"poem-2a15d22ad14c8f5a249f5280","title":"南","author":"徐夤","dynasty":"唐","verses":["罩罩嘉鱼忆此方，送君前浦恨难量。","火山远照苍梧郡，铜柱高标碧海乡。","陆贾几时来越岛，三闾何日濯沧浪。","钟仪冠带归心阻，蝴蝶飞园万草芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-77c55f66-4fa7-41a5-9849-8a1e23cb0899","tags":[]},{"id":"poem-2a19f0180b220605dcdb0dd9","title":"登楚野亭见张舍人题字","author":"张栻","dynasty":"宋","verses":["英豪自昔多遗恨，人物于今正渺然。","来访舍人题字处，淡烟莎草满平川。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-fca29a2d-58be-4b4a-8312-996a3fe335df","tags":[]},{"id":"poem-2a1a9e5776788f036043c425","title":"鹤鸣","author":"佚名","dynasty":"先秦","verses":["鹤鸣于九皋，声闻于野。鱼潜在渊，或在于渚。乐彼之园，爰有树檀，其下维萚。他山之石，可以为错。","鹤鸣于九皋，声闻于天。鱼在于渚，或潜在渊。乐彼之园，爰有树檀，其下维谷。他山之石，可以攻玉。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-183","tags":[]},{"id":"poem-2a1d2f365a3cdd744d51fd48","title":"九叹·思古","author":"刘向","dynasty":"汉","verses":["冥冥深林兮，树木郁郁。","山参差以崭岩兮，阜杳杳以蔽日。","悲余心之悁悁兮，目眇眇而遗泣。","风骚屑以摇木兮，云吸吸以湫戾。","悲余生之无欢兮，愁倥偬于山陆。","旦徘徊于长阪兮，夕彷徨而独宿。","发披披以鬤鬤兮，躬劬劳而瘏悴。","魂俇俇而南行兮，泣沾襟而濡袂。","心婵媛而无告兮，口噤闭而不言。","违郢都之旧闾兮，回湘、沅而远迁。","念余邦之横陷兮，宗鬼神之无次。","闵先嗣之中绝兮，心惶惑而自悲。","聊浮游于山陿兮，步周流于江畔。","临深水而长啸兮，且倘佯而泛观。","兴离骚之微文兮，冀灵修之壹悟。","还余车于南郢兮，复往轨于初古。","道修远其难迁兮，伤余心之不能已。","背三五之典刑兮，绝洪范之辟纪。","播规矩以背度兮，错权衡而任意。","操绳墨而放弃兮，倾容幸而侍侧。","甘棠枯于丰草兮，藜棘树于中庭。","西施斥于北宫兮，仳倠倚于弥楹。","乌获戚而骖乘兮，燕公操于马圉。","蒯聩登于清府兮，咎繇弃而在野。","盖见兹以永叹兮，欲登阶而狐疑。","乘白水而高骛兮，因徙弛而长词。","叹曰：倘佯垆阪沼水深兮，容与汉渚涕淫淫兮，锺牙已死谁为声兮？","纤阿不御焉舒情兮，曾哀凄欷心离离兮，还顾高丘泣如洒兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-54","tags":[]},{"id":"poem-2a1d69ea4bed2a4355c8e4fe","title":"同李中丞洪水亭夜集","author":"皎然","dynasty":"唐","verses":["佳人但莫吹参差，正怜月色生酒巵。","山公取醉不关我，为爱尊前白鹭鹚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-28b7720d-a738-4d2b-b713-20e395c0de75","tags":[]},{"id":"poem-2a234472375e58ccd21a788d","title":"句","author":"释可遵","dynasty":"宋","verses":["掣电引狂雷，昼天忽成暮。","万里泻银河，四簷垂瀑布。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-9e10fa40-a7bf-4a76-842f-362c0d5b4a94","tags":[]},{"id":"poem-2a24eaec660c1f2061f41c47","title":"盘石","author":"无名氏","dynasty":"唐","verses":["海阳泉上山，巉巉尽殊状。","忽然有平石，盘薄千峰上。","寒泉匝石流，悬注几千丈。","有时厌泉湖，爱临一长望。","意出天地间，因为逸民唱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ad2c9baa-86e8-46d6-bed1-b67032d5c2e9","tags":[]},{"id":"poem-2a29fc54c9453fcc4984b31f","title":"小重山·柳暗花明春事深","author":"章良能","dynasty":"宋","verses":["柳暗花明春事深。","小阑红芍药，已抽簪。","雨馀风软碎鸣禽。","迟迟日，犹带一分阴。","往事莫沈吟。","身闲时序好，且登临。","旧游无处不堪寻。","无寻处，惟有少年心。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-189","tags":["宋词三百首"]},{"id":"poem-2a2ae66ef809fab85a686455","title":"偶宴西蜀摩诃池","author":"畅当","dynasty":"唐","verses":["珍木郁清池，风荷左右披。","浅觞宁及醉，慢舸不知移。","荫簟流光冷，凝簪照影欹。","胡为独羁者，雪涕向涟漪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e02943e8-20f0-479f-b3ea-db70190ed5b3","tags":[]},{"id":"poem-2a2b29cfd6332374467524ba","title":"忆故人 一","author":"佚名","dynasty":"唐","verses":["别君彼此两平安，别后恓惶凡几般。","虽然更寄新书去，忆时捻取旧诗看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-94ab29b0-062c-4fa6-ba6b-205ec986e920","tags":[]},{"id":"poem-2a2badae40a94fce950313f2","title":"南山有台","author":"佚名","dynasty":"先秦","verses":["南山有台，北山有莱。乐只君子，邦家之基。乐只君子，万寿无期。","南山有桑，北山有杨。乐只君子，邦家之光。乐只君子，万寿无疆。","南山有杞，北山有李。乐只君子，民之父母。乐只君子，德音不已。","南山有栲，北山有杻。乐只君子，遐不眉寿。乐只君子，德音是茂。","南山有枸，北山有楰。乐只君子，遐不黄耇。乐只君子，保艾尔后。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-171","tags":[]},{"id":"poem-2a2c26f38b23d30be4b9c648","title":"南山田中行","author":"李贺","dynasty":"唐","verses":["秋野明，秋风白，塘水漻漻虫啧啧。","云根苔藓山上石，冷红泣露娇啼色。","荒畦九月稻叉牙，蛰萤低飞陇迳斜。","石脉水流泉滴沙，鬼灯如漆点松花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1d44c69a-e64a-44d4-9576-9ea3bf805533","tags":["秋天","写景"]},{"id":"poem-2a3f331090424317650e59e5","title":"横吹曲辞 入塞曲 一","author":"沈彬","dynasty":"唐","verses":["欲为皇王服远戎，万人金甲鼓鼙中。","阵云暗塞三边黑，兵血愁天一片红。","半夜飜营旗搅月，深秋防戍劒磨风。","谤书未及明君𦶟，卧骨将军已殁功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6281fbf0-c461-4efe-ac5d-26e86d33fc49","tags":[]},{"id":"poem-2a41cde54fe0d5bec47b75a8","title":"水调歌头·静练平千顷","author":"仲并","dynasty":"宋","verses":["静练平千顷，华栋俯中流。","凌晨画戟，来看宿雨断虹收。","八九胸中云梦，三千笔端风月，无处快凝眸。","笑咏一堂上，挥麈气横秋。","俯危阑，红日下，暮云稠。","无穷伟观，祗应天意为君谋。","容我时醒时醉，独泛微烟微雨，浩荡逐轻鸥。","不羡岳阳胜，丹碧耸层楼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-207","tags":[]},{"id":"poem-2a4c9b5e8ac4f37d6bf8d7f5","title":"富贵曲二首 一","author":"贯休","dynasty":"唐","verses":["有金张族，骄奢相续。","琼树玉堂，雕墙绣毂。","纨绮杂杂，钟鼓合合。","美人如白牡丹花，半日只舞得一曲。","乐不乐，足不足，争教他爱山青水绿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8d3f1a1c-b8cf-4d10-9d48-5ef77af95fb1","tags":[]},{"id":"poem-2a5c6bc5fbc31dabb911cf81","title":"省题诗二十一首 上德不德","author":"王棨","dynasty":"唐","verses":["何从称上德，舍德德方全。","圣者如非圣，贤者不自贤。","海宁言我广，神岂谓予玄。","伐善功难立，无为化易宣。","[道]惟闻邃古，理亦愧先天。","欲述犹龙旨，应忘得意筌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ec340e6a-bf9d-45da-b657-23bc4c773464","tags":[]},{"id":"poem-2a5ccc7de45fb994215f0f84","title":"山中寄梁判官","author":"李山甫","dynasty":"唐","verses":["归卧东林计偶谐，柴门深向翠微开。","更无尘事心头起，还有诗情象外来。","康乐公应频结社，寒山子亦患多才。","星郎雅是道中侣，六艺拘牵在隗台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-7e1ca04a-ec8d-4414-8fd3-5f5caf642d02","tags":[]},{"id":"poem-2a634aba31e6a7e8aa7b1dd5","title":"蝶恋花·腊雪初销梅蕊绽","author":"欧阳修","dynasty":"宋","verses":["腊雪初销梅蕊绽。","梅雪相和，喜鹊穿花转。","睡起夕阳迷醉眼。","新愁长向东风乱。","瘦觉玉肌罗带缓。","红杏梢头，二月春犹浅。","望极不来芳信断。","音书纵有争如见。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-631","tags":[]},{"id":"poem-2a654f493dfdf75fd271d800","title":"淮上喜会梁川故人","author":"韦应物","dynasty":"唐","verses":["江汉曾为客，相逢每醉还。","浮云一别后，流水十年间。","欢笑情如旧，萧疎鬓已斑。","何因北归去，淮上对秋山。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a68013c8-4630-41c6-a5ee-a658b57f58fe","tags":["唐诗三百首","友情","五言律诗"]},{"id":"poem-2a66f9cc77860e45932e74c9","title":"稍秋晓坐阁遇舟东下扬州既事寄上族父江阳令","author":"卢僎","dynasty":"唐","verses":["虎啸山城晚，猨鸣江树秋。","红林架落照，青峡送归流。","归流赴淮海，征帆下扬州。","族父江阳令，盛业继前修。","文掩崔亭伯，德齐陈太丘。","时哉惜未与，千载且为俦。","忆昔山阳会，长怀东上游。","称觞阮林下，赋雪谢庭幽。","道浓礼自略，气舒文转遒。","高情薄云汉，酣态坐芳洲。","接席复连轸，出入陪华辀。","独善与兼济，语默奉良筹。","岁月欢无已，风雨暗飕飕。","掌宪时持节，为邦邈海头。","子人惠虽树，苍生望且留。","微躬趋直道，神甸忝清猷。","仙台适西步，蛮徼忽南浮。","宇内皆安乐，天涯独远投。","忠信徒坚仗，神明岂默詶。","观生海漫漫，稽命天悠悠。","云昏巴子峡，月远吴王楼。","怀昔明不寐，悲令岁属周。","喟无排云翮，暂得抒离忧。","空洒沾红泪，万里逐行舟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-be632a1d-3ed9-4a6d-84b8-5f8013d380eb","tags":[]},{"id":"poem-2a6a78d0c09e7ea09f4fdcb4","title":"庙山道中","author":"王同祖","dynasty":"宋","verses":["萧萧疏雨点孤蓬，舟子招呼语顺风。","小麦青青春恰半，一犂江上看田翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f8431ec2-c85e-4235-91ec-782bc116df67","tags":[]},{"id":"poem-2a73b5203d096549bfa62f67","title":"戏赠阌乡秦少公短歌","author":"杜甫","dynasty":"唐","verses":["去年行宫当太白，朝回君是同舍客。","同心不减骨肉亲，每语见许文章伯。","今日时清两京道，相逢苦觉人情好。","昨夜邀欢乐更无，多才依旧能潦倒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0f6b5485-6ead-48e3-b211-46aaa1be1238","tags":[]},{"id":"poem-2a73c16e02e1b7449fe5b1f2","title":"塞上行","author":"曹松","dynasty":"唐","verses":["上将拥黄须，安西逐指呼。","离乡俱少壮，到碛减肌肤。","风雪夜防塞，腥膻朝系胡。","为君乐战死，谁喜作征夫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4c1c0647-10d7-48b0-a4a4-bd88242b0354","tags":[]},{"id":"poem-2a74b2308f1e9d34957ce948","title":"偈 二","author":"缘观","dynasty":"唐","verses":["红焰藏吾身，何须塔庙新。","有人相肯重，灰里邈全真。","（《景德传灯录》卷二四、《五灯会元》卷十四。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f6203ae0-f071-47e8-9790-3a50a2c605f6","tags":[]},{"id":"poem-2a78d900b9ef2045a9d1e58c","title":"下地日侍陆侍郎御䜩赋得落花（「下地日」，疑应作「下第日」。）","author":"王贞白","dynasty":"唐","verses":["何处足落花，漂泥与藉沙。","春深上林苑，日晚五侯家。","遍地轻难扫，当风势易斜。","无心媿蜂蝶，来岁即荣华。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5b380166-5cf7-45f5-942c-37bc4d7c8a9a","tags":[]},{"id":"poem-2a83a68b20f85cab27512061","title":"江村即事","author":"司空曙","dynasty":"唐","verses":["钓罢归来不系船，江村月落正堪眠。","纵然一夜风吹去，只在芦花浅水边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-64d3f88f-ce69-4ea3-8646-5635a7ed9139","tags":["乡村","生活","写景","农村"]},{"id":"poem-2a8f248d11876c5c73dba773","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["脚下转身，相公特特，教请夫人。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2721","tags":[]},{"id":"poem-2a904597b29a7cec78905274","title":"和贾舍人早朝大明宫之作","author":"王维","dynasty":"唐","verses":["绛帻鸡人送晓筹，尚衣方进翠云裘。","九天阊阖开宫殿，万国衣冠拜冕旒。","日色才临仙掌动，香烟欲傍衮龙浮。","朝罢须裁五色诏，佩声归向凤池头。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a364504e-3cfc-44c6-9203-173856452cdd","tags":["唐诗三百首","宫廷","七言律诗","早朝"]},{"id":"poem-2a924b6c890ead26e6e301b4","title":"隰有苌楚","author":"佚名","dynasty":"先秦","verses":["隰有苌楚，猗傩其枝，夭之沃沃，乐子之无知。","隰有苌楚，猗傩其华，夭之沃沃。乐子之无家。","隰有苌楚，猗傩其实，夭之沃沃。乐子之无室。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-147","tags":[]},{"id":"poem-2a9543ff344e134704893280","title":"题灵泉寺","author":"程序","dynasty":"唐","verses":["烟景[昼]（尽）冥冥，楼台隐翠屏。","猨攀太子树，鸟听《法王经》。","悟理心无著，求缘塔有灵。","回车犹未远，日暮数峰青。","（亦见《安阳县金石录》。","）（按此诗与徐源、徐淮诗刻一石，诗下原题「广平程序字[土]〖古〗伦」七字。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-bc267111-b4c6-43cf-8ce0-bedd090054cf","tags":[]},{"id":"poem-2a9f289162b1cd7cb3c2de76","title":"双双燕·过春社了","author":"史达祖","dynasty":"宋","verses":["过春社了，度帘幕中间，去年尘冷。","差池欲住，试入旧巢相并。","还相雕梁藻井。","又软语、商量不定。","飘然快拂花梢，翠尾分开红影。","芳径。","芹泥雨润。","爱贴地争飞，竞夸轻俊。","红楼归晚，看足柳昏花暝。","应自栖香正稳。","便忘了、天涯芳信。","愁损翠黛双蛾，日日画阑独凭。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-179","tags":["宋词三百首"]},{"id":"poem-2aa34b2f4ea0345d721e1bd5","title":"白鼋涡","author":"王维","dynasty":"唐","verses":["南山之瀑水兮，激石瀥瀑似雷惊。","人相对兮，不闻语声。","翻涡跳沫兮苍苔湿，藓老且厚，春草为之不生。","兽不敢惊动，鸟不敢飞鸣。","白鼋涡涛戏濑兮，委身以纵横。","王人之仁兮，不网不钓，得遂性以生成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e7f7681d-2be9-4d46-8186-e3fe25b52634","tags":[]},{"id":"poem-2aa8a43047623b1efe6679df","title":"郊庙歌辞 五郊乐章 黄帝宫音 舒和","author":"魏征","dynasty":"唐","verses":["御征乘宫出郊甸，安歌率舞递将迎。","自有云门符帝赏，犹持雷鼓答天成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3a12c6ba-c4d8-4b41-9b67-b6c3be170ac4","tags":[]},{"id":"poem-2ab25e27d5e0cb5a9f992f5e","title":"翔隼歌送王端公","author":"皎然","dynasty":"唐","verses":["古人赏神骏，如何秋隼击。","独立高标望霜翮，应看天宇如咫尺。","低回拂地凌风翔，鹏雏敢下鴈断行。","晴空四顾忽不见，有时独出青霞傍。","穷阴万里落寒日，气杀草枯增奋逸。","云塞斜飞搅叶迷，雪天直上穿花疾。","见君高情有所属，赠别因歌翔隼曲。","离亭惨惨客散时，歌尽路长意不足。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8151068a-111c-4566-8baf-ec3d41d23356","tags":[]},{"id":"poem-2ab40727d5098cc5043f9555","title":"俯吐蕃禁门观田判官赠向将军真言口号（项云「俯」当作「附」，下夺「近」字，「附近」为接近、靠近之意。）","author":"马云奇","dynasty":"唐","verses":["怪来偏得主君怜，料取分明在眼前。","说相未应惊䴏鸰，看心且爱直如弦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4ca64d64-e6c3-4320-b42a-ba0ee8d5d6a8","tags":[]},{"id":"poem-2adabb4fb4b6aa766424fb21","title":"子规","author":"鲍溶","dynasty":"唐","verses":["中林子规啼，云是古蜀帝。","蜀帝胡为鸟，惊急如罪戾。","一啼艳阳节，春色亦可替。","再啼孟夏林，密叶堪委翳。","三啼凉秋晓，百卉无生意。","四啼玄冥冬，云物惨不霁。","芸黄壮士发，沾洒妖姬袂。","悲深寒乌雏，哀掩病鹤翅。","胡为托幽命，庇质无完毳。","戚戚含至冤，卑卑忌群势。","吾闻凤皇长，羽族皆受制。","盍分翡翠毛，使学鹦鹉慧。","敌怨不在弦，一哀尚能继。","那令不知休，泣血经世世。","古风失中和，衰代因郑卫。","三叹尚淫哀，向渴嘻流涕。","如因异声感，乐与中肠契。","至教一昏芜，生人遂危脆。","古意叹通近，如上青天际。","荼蓼久已甘，空劳菫葵惠。","谁闻子规苦，思与正声计。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a71418ae-c493-429c-a3b1-a56a5a21887d","tags":[]},{"id":"poem-2aea767cdff9f21a58c32f8a","title":"荷叶杯·知己一人谁是","author":"纳兰性德","dynasty":"清","verses":["知己一人谁是。","已矣。","赢得误他生。","有情终古似无情，别语悔分明。","莫道芳时易度，朝暮。","珍重好花天。","为伊指点再来缘，疏雨洗遗钿。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-152","tags":[]},{"id":"poem-2aecb4defd45a803fef999d6","title":"和韦舍人早朝","author":"沈佺期","dynasty":"唐","verses":["阊阖连云起，岩廊拂雾开。","玉珂龙影度，珠履雁行来。","长乐宵钟尽，明光晓奏催。","一经推旧德，五字擢英才。","俨若神仙去，纷从霄汉廻。","千春奉休历，分禁喜趋陪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-69292dcc-3a7e-4048-badd-aa403d6b35c7","tags":[]},{"id":"poem-2aeefdafdceee78d080115b3","title":"贺殷游二舍人入翰林江给事拜中丞","author":"徐铉","dynasty":"宋","verses":["清晨待漏独徘徊，霄汉悬心不易裁。","阁老深严归翰苑，夕郎威望拜霜台。","青绫对覆蓬壶晚，赤棒前驱道路开。","犹有西垣厅记在，莫忘同草紫泥来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-879c1892-8932-4534-a7de-9d37f73c2d1a","tags":[]},{"id":"poem-2af4e18fdc8d9a0cb9f6b8d2","title":"百喜图","author":"释居简","dynasty":"宋","verses":["比翼飞梁跨碧浔，玉绳低转夜沈沈。","一年一度丛霄去，却下人间送好音。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-567b0e87-e814-4b97-bd08-c0af8f4721b5","tags":[]},{"id":"poem-2af4ea5dc1bbdd43d0aae129","title":"前出塞九首 四","author":"杜甫","dynasty":"唐","verses":["送徒既有长，远戍亦有身。","生死向前去，不劳吏怒嗔。","路逢相识人，附书与六亲。","哀哉两决绝，不复同苦辛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-253b667d-e9bb-44ec-8ea9-03e1d552d9a7","tags":[]},{"id":"poem-2af94da716a4c0694f5dc09f","title":"锁南枝","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［旦］休发怒，免性焦，一言望乞听奴告。","这聘礼荆钗，休恁看得小。","［净］是金的？［旦］非是金。","［丑］敢是宝。","［旦］非是宝。","［净］非金非宝，要他何用？［旦］将来聘奴家，一似孟德耀。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8084","tags":[]},{"id":"poem-2afa0eb3b857e9e4c60268cf","title":"登米老庵呈天启学士","author":"米芾","dynasty":"宋","verses":["我居为江山，亦不为像法。","劫火色相空，未觉眼界乏。","屹然留西庵，使我老境惬。","卫公精爽在，千古对岌嶪。","公来不可作，登临浩相接。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c8f08b25-58a9-4562-b3b4-bdd9ba67de53","tags":[]},{"id":"poem-2afaf8c03a9ff3a5d4380fcf","title":"望江南·多少泪","author":"李煜","dynasty":"五代","verses":["多少泪，断脸复横颐。","心事莫将和泪说，凤笙休向泪时吹。","肠断更无疑。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-9","tags":[]},{"id":"poem-2afec412857069febf0fe408","title":"奉和正旦赐宰臣栢叶应制","author":"武平一","dynasty":"唐","verses":["绿叶迎春绿，寒枝历岁寒。","愿持柏叶寿，长奉万年欢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0348db03-dcf5-4e23-ac3c-cbfa186ebae3","tags":[]},{"id":"poem-2b0427508223d8073100db28","title":"杪秋夜直","author":"郑畋","dynasty":"唐","verses":["蘂宫裁诏与宵分，虽在青云忆白云。","待报君恩了归去，山翁何急草移文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-84fed06b-c500-4cdb-9336-32c87acd98ad","tags":[]},{"id":"poem-2b0be3b35c294c2bff05ee0e","title":"送玄同真人李抱朴谒灊山仙祠","author":"明皇帝","dynasty":"唐","verses":["城阙天中近，蓬瀛海上遥。","归期千载鹤，春至一来朝。","采药逢三秀，餐霞卧九霄。","参同如有旨，金鼎待君烧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3175be79-7852-4d21-ae00-6e99046947d5","tags":[]},{"id":"poem-2b16d483527e75bc45a6a15d","title":"送寒岩归士","author":"徐凝","dynasty":"唐","verses":["不挂丝纩衣，归向寒岩栖。","寒岩风雪夜，又过岩前溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-16f7c052-7358-4b2d-996f-ea11c6f60009","tags":[]},{"id":"poem-2b1861eb3301e4937915fe85","title":"酬当涂何户曹畏斋金陵三篇见寄兼柬饷台上幕许从道  其三","author":"释居简","dynasty":"宋","verses":["松根葛藟亟扳缘，势极青冥恨不前。","鶑閟好音春不响，鹤嫌遗臭夜移眠。","回头华表一千载，开眼檀萝十九年。","想见息阴羞恶木，断魂岭海吊诸贤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4a9ea0e2-73e4-4182-a87e-99647d33ffba","tags":[]},{"id":"poem-2b1c9c88976067cd8c72f5f5","title":"南轩木犀","author":"张栻","dynasty":"宋","verses":["不随秋月閟天香，冰雪丛中见缕黄。","却得清寒惜花地，少须梅影慰孤芳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-9a3eee4c-a986-4ee6-a174-48064ce114f7","tags":[]},{"id":"poem-2b29218dca2bd653d360585c","title":"行官张望补稻畦水归","author":"杜甫","dynasty":"唐","verses":["东屯大江北，百顷平若案。","六月青稻多，千畦碧泉乱。","插秧适云已，引溜加溉灌。","更仆往方塘，决渠当断岸。","公私各地著，浸润无天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生银汉。","欧鸟镜里来，关山云边看。","秋菰成黑米，精凿传白粲。","玉粒足晨炊，红鲜任霞散。","终然添旅食，作苦期壮观。","遗穗及众多，我仓戒滋蔓。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ed927451-c3fd-4566-97a2-c86f8c2fa756","tags":[]},{"id":"poem-2b2dd85236401ae7e6a9b10e","title":"霜天晓角·晚晴风歇","author":"范成大","dynasty":"宋","verses":["晚晴风歇。","一夜春折威。","脉脉花疏天淡，云来去、数枝雪。","胜绝。","愁亦绝。","此情谁共说。","惟有两行低雁，知人倚、画楼月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-276","tags":["宋词三百首"]},{"id":"poem-2b352d85a698772e2e3aa4b0","title":"和张文裕初寒十首  其一","author":"司马光","dynasty":"宋","verses":["何处初寒好，初寒郏鄏城。","垂绅多俊彦，列第尽公卿。","裘马过从盛，门阑洒扫清。","谁家拥兽炭，尽日管弦声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-51cbe46d-0a56-405f-b9cc-ba53e903618c","tags":[]},{"id":"poem-2b40307cf5084c9c83b0471d","title":"九日蓝耕会饮","author":"杜甫","dynasty":"唐","verses":["老去悲秋强自宽，兴来今日尽君欢。","羞将短发还吹帽，笑倩旁人为正冠。","蓝水远从千涧落，玉山高并两峰寒。","明年此会知谁健，醉把茱萸仔细看。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-九日藍耕會飲","tags":[]},{"id":"poem-2b453c1992207a845f6f5449","title":"病中客散复言怀","author":"刘言史","dynasty":"唐","verses":["华发离披卧满头，暗虫衰草入乡愁。","枕前人去空庭暮，又见芭蕉白露秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9298909a-189b-4e81-9e2e-9a2ae10a0735","tags":[]},{"id":"poem-2b4778cca6272842ee7365f1","title":"九罭","author":"佚名","dynasty":"先秦","verses":["九罭之鱼，鳟鲂。我觏之子，衮衣绣裳。","鸿飞遵渚，公归无所，于女信处。鸿飞遵六，公归不复，于女信宿。","是以有衮衣兮，无以我公归兮，无使我心悲兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-158","tags":[]},{"id":"poem-2b4dfa4e0015008cc89a996e","title":"寒夜闻霜钟","author":"卢景亮","dynasty":"唐","verses":["洪钟发长夜，清响出层岑。","暗入繁霜切，遥传古寺深。","何城乱远漏，几处杂疎砧。","已警离人梦，仍沾旅客襟。","待时当命侣，抱器本无心。","傥若无知者，谁能设此音。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b164994f-94c1-4b16-920a-0725c091bedb","tags":[]},{"id":"poem-2b5409e06b66561f09bacec9","title":"江楼有感","author":"赵嘏","dynasty":"唐","verses":["独上江楼思渺然，月光如水水如天。","同来玩月人何在，风景依稀似去年。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-江樓有感","tags":[]},{"id":"poem-2b5d385260452fad3d228db5","title":"宴山亭・燕山亭·幽梦初回","author":"张","dynasty":"宋","verses":["幽梦初回，重阴未开，晓色吹成疏雨。","竹槛气寒，蕙畹声摇，新绿暗通南浦。","未有人行，才半启、回廊朱户。","无绪。","空望极霓旌，锦书难据。","苔径追忆曾游，念谁伴、秋千采绳芳柱。","犀奁黛卷，凤枕云孤，应也几番凝伫。","怎得伊来，花雾绕、小堂深处。","留住。","直到老、不教归去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-119","tags":["宋词三百首"]},{"id":"poem-2b608f3be66ff185760bf647","title":"杂诗三首 三","author":"沈佺期","dynasty":"唐","verses":["闻道黄龙戍，频年不解兵。","可怜闺里月，长在汉家营。","少妇今春意，良人昨夜情。","谁能将旗鼓，一为取龙城。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1fb10ea4-f46c-4c08-bd06-f039f1907be6","tags":["唐诗三百首","战争","妇女","五言律诗","相思"]},{"id":"poem-2b64f321ad243e37a6ed53cf","title":"送魏骑曹充宇文侍御判官分按山南","author":"孙逖","dynasty":"唐","verses":["云雨阳台路，光华驿骑巡。","劝农开梦土，恤隐惠荆人。","楼迥吟黄鹤，江长望白苹。","观风布明诏，更是汉南春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5bd0fc18-bedb-4192-a865-06b3578c688e","tags":[]},{"id":"poem-2b6b994b9b5cd7bc9b241d6a","title":"兵要望江南 《周易》占候第二十六（三十七首） 一","author":"易静","dynasty":"唐","verses":["圣人造，作《易》变爻辞。","掷卦要知凶与吉，切须盥手动占仪，恳意合天机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d1631f0e-7f92-4aba-ab8b-5384e54563a9","tags":[]},{"id":"poem-2b6c48f86a1fb9af80118d90","title":"古鲍老","author":"杨景贤","dynasty":"元","verses":["手提着太阿，碧澄澄恰如三尺波。","额攒着翠娥，恶狠狠怒如千丈火。","狂旗磨．战鼓敲，妖兵和。","你便吃了灵丹数颗，争似我风声偏大，半合儿敢着你难捞摸。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2352","tags":[]},{"id":"poem-2b79c0a1bda1b8bdc8783351","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十九","author":"易静","dynasty":"唐","verses":["伤门内，捕盗可移趋。","杜门有难前潜吉，景门凡事不安居，献策稍通疎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-404ece23-7f62-4a8a-b417-9530504fb913","tags":[]},{"id":"poem-2b7a783b922c80a0e108116f","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(外)不必泪涟涟，这相逢非偶然。","同临任所为姻眷，聊附寸笺，饶州报传，管教你夫妇重相见。","(合)免忧煎，夫妻有日，重得遇椿萱。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8219","tags":[]},{"id":"poem-2b80e6d3aa927da8a28030c5","title":"送沈亚之赴郢掾","author":"徐凝","dynasty":"唐","verses":["千万乘骢沈司户，不须惆怅郢中游。","几年白雪无人唱，今日唯君上雪楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-27c2fa43-3722-428f-a7ac-0ac960801c08","tags":[]},{"id":"poem-2b838e05322f4bcb4241a48e","title":"和洛州康士曹庭芝望月有怀","author":"沈佺期","dynasty":"唐","verses":["天使下西楼，光含万象秋。","台前疑挂镜，帘外似悬钩。","张尹将眉学，班姬取扇俦。","佳期应借问，为报在刀头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-49be49dc-b305-4bba-9319-72aa0a8186b1","tags":[]},{"id":"poem-2b8c2c9b801e8d886943fbb6","title":"上冯使君渡水僧障子","author":"贯休","dynasty":"唐","verses":["跣足拄巴藤，潺湲渡几曾。","尽权无著印，不是登闲僧。","熊耳应初到，牛头始去登。","画来偏觉好，将寄柳吴兴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3ff84338-4c67-4d21-a9ca-21fd8a7ce7ad","tags":[]},{"id":"poem-2b8db93e1086f6ca59e4eb31","title":"角弓","author":"佚名","dynasty":"先秦","verses":["骍骍角弓，翩其反矣。兄弟婚姻，无胥远矣。","尔之远矣，民胥然矣。尔之教矣，民胥效矣。","此令兄弟，绰绰有裕。不令兄弟，交相为愈。","民之无良，相怨一方。受爵不让，至于已斯亡。","老马反为驹，不顾其后。如食宜饇，如酌孔取。","毋教猱升木，如涂涂附。君子有徽猷，小人与属。","雨雪瀌瀌，见𬀪曰消。莫肯下遗，式居娄骄。","雨雪浮浮，见𬀪曰流。如蛮如髦，我是用忧。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-222","tags":[]},{"id":"poem-2b966ad22e06f80f98b566ab","title":"酬施先辈","author":"孟简","dynasty":"唐","verses":["襄阳才子得声多，四海皆传古镜歌。","乐府正声三百首，[梨]园新入教青娥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a4c79c77-63ae-4bf2-9f93-5c7132301dd5","tags":[]},{"id":"poem-2b984c734b357584bce6cb3c","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(末)状元休忧虑，且把情怀暂舒。","人妻聚散生前注，这离别虽说离别苦，想姻缘不入姻缘簿。","听取一言伸覆：须信人生万事，莫逃天数。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8251","tags":[]},{"id":"poem-2ba9d44752d2fad7cd122b61","title":"看缙云山图","author":"李翔","dynasty":"唐","verses":["谓见仙都二十年，（谓，项疑当作「未」。","）忽逢图画顿欣然。","云岩不似人间世，物象翻疑洞里天。","迥压鳌头当海眼，直侵鹏路倚星躔。","顶湖纵去无多地，空见霜流百丈泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-45ebc19f-70f0-4e18-80d3-e66aa770dae8","tags":[]},{"id":"poem-2bb048a29ab1cbec6f57ddc2","title":"赠李昉（题拟）","author":"李沼","dynasty":"唐","verses":["反观西里盛，世世秉钧衡。","（见《增修诗话总龟》卷三引《翰府名谈》。","）（〖1〗《翰府名谈》：「丞相李文正公昉少年时尝以诗呈叔侍中，览而喜，赠之诗曰〖略〗。","后文正果大用，诏赐所居为谢元卿秉钧里。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7841b212-63a1-41a9-b073-2484254085a5","tags":[]},{"id":"poem-2bb2fadb43b0c77fe3ec0fd2","title":"红绣鞋","author":"无名氏《张协状元》","dynasty":"元","verses":["小二在何处说话？(丑)在卓下。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2555","tags":[]},{"id":"poem-2bbb3a5cbe62b359fcae6744","title":"滴溜子","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["天应念，天应念，蔡邕拜祷：双亲的，双亲的，死生未保，可怜恩深难报。","一封奏九重，知他听否？会合分离，都在这遭。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5030","tags":[]},{"id":"poem-2bd0effbf5f7fbc3574d50f9","title":"荔枝五首  其五","author":"李纲","dynasty":"宋","verses":["百马崩腾耆旧悲，只今戈戟暗江湄。","自知疏拙蒙恩重，犹得南来食荔枝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6fdefac5-7f01-451c-ac6f-45732454a92a","tags":[]},{"id":"poem-2be8a3700fc46ae7ae725ed6","title":"霜月","author":"李商隐","dynasty":"唐","verses":["初闻征雁已无蝉，百尺楼台水接天。","青女素娥俱耐冷，月中霜里斗婵娟。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-霜月","tags":[]},{"id":"poem-2bec37a890f2524beae8aa2a","title":"旄丘","author":"佚名","dynasty":"先秦","verses":["旄丘之葛兮，何诞之节兮。叔兮伯兮，何多日也？","何其处也？必有与也！何其久也？必有以也！","狐裘蒙戎，匪车不东。叔兮伯兮，靡所与同。","琐兮尾兮，流离之子。叔兮伯兮，褎如充耳。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-36","tags":[]},{"id":"poem-2bf7940d58727c93963c0e86","title":"耸翠峰题石（原注：峰在袁州府城西三十里。）","author":"卢肇","dynasty":"唐","verses":["耸翠峰高千百尺，四时常似莓蓝色。","卓然万古镇祗园，世代鬼工驱不得。","巍巍直上插青天，远疑似与天相连。","韎临下视群山小，千里平铺在眼（一作「目」）前。","藤蔓交加生薜荔，土毛苍藓相蒙蔽。","风翦云开雨歇时，飞出一山新翡翠。","日回影倒落前溪，烟波湛湛浸琉璃。","更将何物可比类，分明一只擎天柱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-16598afb-e829-460d-8f4d-4cb6298e9a7d","tags":[]},{"id":"poem-2bfa1a952d22b69d7ff7cf1b","title":"暮春寻终南柳处士","author":"李端","dynasty":"唐","verses":["庞眉一居士，鹑服隐尧时。","种荳初成亩，还丹旧日师。","入溪花径远，向岭鸟行迟。","紫葛垂苔壁，青菰映柳丝。","偶来尘外事，暂与素心期。","终恨游春宫，同为岁月悲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b6283b73-915a-4959-8579-19cc7e057f69","tags":[]},{"id":"poem-2c0aa38146c13cf7caf35329","title":"应举日寄兄弟","author":"朱可名","dynasty":"唐","verses":["废刈镜湖田，上书紫阁前。","愁人久委地，诗道未闻天。","不是烧金手，徒抛钓月船。","多惭兄弟意，不敢问林泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-49c442a7-b1e4-4871-bb55-9e18a63d8a4e","tags":[]},{"id":"poem-2c210f99f0107c6cdda0b12e","title":"送僧归玉泉寺","author":"刘得仁","dynasty":"唐","verses":["玉泉归故刹，便老是僧期。","乱木孤蝉后，寒山绝鸟时。","若寻流水去，转出白云迟。","见说千峰路，溪深复顶危。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-135b439d-b60c-4a42-8d0c-22cc25e42426","tags":[]},{"id":"poem-2c22ee4621607244b8636868","title":"赠祠部令狐郎中","author":"马戴","dynasty":"唐","verses":["官初执宪称雄才，省转为郎雅望催。","待制松阴移玉殿，分宵露气静天台。","算棋默向孤云坐，随鹤闲穷片水回。","忽忆十年相识日，小儒新自海边来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9ab77b05-8e8a-49e0-9eca-e04ed814f349","tags":[]},{"id":"poem-2c2c04488ef53d14f8fcf331","title":"石留","author":"赵文","dynasty":"宋","verses":["江流汤汤，日夜不休。","瞿塘滟滪，屹然不流。","人心人心，反复难任。","昨日朱丝琴，今日白头吟。","望夫石，留到今。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-d0158ad6-201c-49f5-928f-1466002a1c5b","tags":[]},{"id":"poem-2c2c566f0b9875b77da1082e","title":"金谷览古","author":"徐凝","dynasty":"唐","verses":["金谷园中数尺土，问人知是绿珠台。","绿珠歌舞天下绝，唯与石家生祸胎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-60bc0251-0d8a-488b-858c-310f6559d0d0","tags":[]},{"id":"poem-2c2c70ec1ab7b1e418ca2a61","title":"赠胡居士","author":"李端","dynasty":"唐","verses":["孔融过五十，海内故人稀。","相府恩犹在，知君未拂衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5f9b6ea2-3e56-453a-9d39-5e9bef673fb9","tags":[]},{"id":"poem-2c385bcf071450fc42cf772e","title":"鹿鸣宴","author":"张栻","dynasty":"宋","verses":["从昔山川夸八桂，只今文物盛南州。","秋风万里携书剑，春日端门拜冕旒。","圣世取才先实用，儒生报国岂身谋。","且看廷策三千字，为写平时畎亩忧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-71221f87-615f-443c-8960-8d57d5fbfe4e","tags":[]},{"id":"poem-2c396467097138bad4616e81","title":"赠馆驿刘巡官","author":"赵嘏","dynasty":"唐","verses":["云别青山马踏尘，负才难觅作闲人。","莫言馆驿无公事，诗酒能消一半春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4e8cb1e3-f087-47ba-ba7c-ec284211e11d","tags":[]},{"id":"poem-2c3f2976e692855df16ea583","title":"贺圣朝","author":"施惠《幽闺记》","dynasty":"元","verses":["(小生上)斩龙射虎威风，擒王捉将英雄。","锦征袍相称茜巾红，镇山北山东。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2919","tags":[]},{"id":"poem-2c40a8be7109fbc1d3a3b061","title":"送龙学和寄王元之郎中","author":"张徽","dynasty":"宋","verses":["未持双节去朝元，玉陛犹虚侍从班。","龟洛旧游天直上，鸡林新句海中间。","品流有日归陶冶，隐逸无时奉宴闲。","鹤驭仙游何处所，轩皇冠剑在桥山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8bc7e50c-763b-4104-9161-839c1d86beb0","tags":[]},{"id":"poem-2c45054f964dc5d2c2a4d716","title":"不雨","author":"释居简","dynasty":"宋","verses":["田欲龟文晓尚龟，高高如燎恐云焦。","未应天上无炎热，可是山中欠燮调。","草偃风颠凉自至，雨随车后暑应消。","冷菰寒玉关心外，却立虚庭望泬寥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-aacbde8b-adf9-4438-ada6-a4dbc143c760","tags":[]},{"id":"poem-2c46979caec1baad2f952147","title":"曳鼎歌","author":"则天皇后","dynasty":"唐","verses":["羲农首出，轩昊膺期。","唐虞继踵，汤禹乘时。","天下光宅，海内雍熙。","上玄降鉴，方建隆基。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-623de378-ac00-4dec-99c2-10e4668ff7ce","tags":[]},{"id":"poem-2c48fd1854cd16ff89000b88","title":"死马赋（伯三六一九）","author":"刘希移","dynasty":"唐","verses":["连山四望何高高，良马本代君子劳；燕地冰坚伤冻骨，胡天霜缩落缩寒毛。","愿君回来乡山道，道傍青青饶美草；鞭策寻途未敢迷，希君少留卷（养）[二]疲老。","（「卷」，原卷作「养」。","）君其去去途未穷，悲鸣羸卧此山中；桃花零落三春月，桂枝摧折九秋风。","昔是浮光疑曳练，常时蹑景如流电；长揪尘暗形影遥，（「长揪」，蒋、项皆云当作「长楸」。","）上策（林）[三]（「策」，原卷作「叶」。","）日明踪迹偏（徧）。","汉女[四]弹弦怨离别，楚王兴歌苦征战；赤血沾沾（君）[五]君不知，白骨辞君君不见。","少年驰射出幽幷，高秋摇落重横行；云中想见游龙影，月下思闻飞鹊声。","千里相思浩如失，一代英雄从此毕；盐车垂耳不知年，粧楼画眉宁记日？","高门待封杳无期，迁乔题柱即长辞；（「迁乔」，蒋校作「僊桥」，指成都升僊桥，用《华阳国志》载司马相如事。","）八骏驰名终已矣，千金卖（买）骨复何时？","（[一]刘希夷的诗在敦煌卷子里面传钞的不少，如《白头老翁》〖《全唐诗》作《代悲白头翁》〗有三个写本，并且题着刘希夷的名字。","和《死马赋》写在同一卷子〖伯三六一九〗上的，还有《捣衣篇》和《北邙篇》〖《全唐诗》作《洛川怀古》〗，《捣衣篇》也题着刘希夷的名字。","此题作「刘希移」，误。","[二]依俞、刘说。","[三]依刘校。","[四]刘云：「汉女谓乌孙公主，见石崇《王明君辞序》。","」[五]依俞校。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1bcc31b2-eb4e-4ef2-8393-8f7db818f4a9","tags":[]},{"id":"poem-2c6ae989a6671fb4e3e81d17","title":"送远客","author":"张籍","dynasty":"唐","verses":["憔悴远归客，殷勤欲别杯。","九星坛下路，几日见重来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-49ce4f86-6999-48a4-8d85-59851b6f62fd","tags":[]},{"id":"poem-2c710a345cccc1ef82b62aca","title":"避暑二首 一","author":"徐凝","dynasty":"唐","verses":["一株金染密，数亩碧鲜疎。","避暑临溪坐，何妨直钓鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9d394ffc-594e-4190-92d4-1d24efe48cce","tags":[]},{"id":"poem-2c86b452f0dc984ebf5ecc6b","title":"木兰花・玉楼春·谈围曾蔽青绫帐","author":"葛胜仲","dynasty":"宋","verses":["谈围曾蔽青绫帐。","林下中年敦素尚。","烟波偶趁一帆风，却锁云扃来就养。","自从悟得空无相。","身把虚空来作样。","大千沙界抹为尘，未比无生真寿量。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-29","tags":[]},{"id":"poem-2c8cca83ac804d1ba0cc1d40","title":"拂霓裳·喜秋成","author":"晏殊","dynasty":"宋","verses":["喜秋成。","见千门万户乐升平。","金风细，玉池波浪縠文生。","宿露沾罗幕，微凉入画屏。","张绮宴，傍熏炉蕙炷、和新声。","神仙雅会，会此日，象蓬瀛。","管弦清，旋翻红袖学飞琼。","光阴无暂住，欢醉有闲情。","祝辰星。","愿百千为寿、献瑶觥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-538","tags":[]},{"id":"poem-2c905fd0a13f0a0640a40d35","title":"宿青溪驿奉怀张员外十五兄之绪","author":"杜甫","dynasty":"唐","verses":["漾舟千山内，日入泊枉渚。","我生本飘飘，今复在何许。","石根青枫林，猿鸟聚俦侣。","月明游子静，畏虎不得语。","中夜怀友朋，乾坤此深阻。","浩荡前后间，佳期付荆楚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-71817edb-5481-405b-90ae-0d67ed39c59c","tags":[]},{"id":"poem-2ca41d92f44736c60679b119","title":"句 一","author":"罗隐","dynasty":"唐","verses":["曹韩沙嘴团，铜陵出状元。","（见影印天一阁藏本《嘉靖池州府志》卷一。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c74c46c0-1260-47bf-b1c9-f474863db70a","tags":[]},{"id":"poem-2caf92dc8ab378e00573c726","title":"长干曲四首 一","author":"崔颢","dynasty":"唐","verses":["君家何处住？妾住在横塘。","停船暂借问，或恐是同乡。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c39225f9-16b2-4713-a11c-d7030ec3b1c9","tags":["唐诗三百首","孤独","女子","思乡","乐府"]},{"id":"poem-2cbe03dff686a4c41bf951c2","title":"送邓器先赴罗田尉五首  其四","author":"曾协","dynasty":"宋","verses":["古郡有奇观，祖祖灯相传。","子来后往哲，青山古依然。","纷纷簿领中，深观常安然。","但使内外尽，饥餐困须眠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-953da322-65f5-415d-92a4-be9b1dbfcaca","tags":[]},{"id":"poem-2cd5c35c7ae9523239d1f5b8","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十二","author":"易静","dynasty":"唐","verses":["占行路，逐日定占之。","有气青龙并六合，钱财仓库定无疑，多获彩缣持。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f4980e95-6646-491a-b1d6-182f73e05657","tags":[]},{"id":"poem-2cd69070911be3c7270473a0","title":"哀王孙","author":"杜甫","dynasty":"唐","verses":["长安城头头白乌，夜飞延秋门上呼。","又向人家啄大屋，屋底达官走避胡。","金鞭断折九马死，骨肉不待同驰驱。","腰下实玦青珊瑚，可怜王孙泣路隅。","问之不肯道姓名，但道困苦乞为奴。","已经百日窜荆棘，身上无有完肌肤。","高帝子孙尽隆准，龙种自与常人殊。","豺狼在邑龙在野，王孙善保千金躯。","不敢长语临交衢，且为王孙立斯须。","昨夜东风吹血腥，东来橐驼满旧都。","朔方健儿好身手，昔何勇锐今何愚。","窃闻天子已传位，贤德北服南单于。","花门剺面请雪耻，慎勿出口他人狙。","哀哉王孙慎勿疎，五陵佳气无时无。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bd7949f8-c961-4bfd-a307-1fe9e621028c","tags":["唐诗三百首","叙事","抒情","新乐府辞","乐府","写鸟","鸟"]},{"id":"poem-2cdc91b8314dba7a5a526044","title":"人日剪彩","author":"徐延寿","dynasty":"唐","verses":["闺妇持刀坐，自怜裁剪新。","叶催情缀色，花寄手成春。","帖燕留妆户，黏鸡待饷人。","擎来问夫壻，何处不如真。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8d7bd64d-8899-4188-80fe-58b3a0063af2","tags":[]},{"id":"poem-2ce6b60b4a02fe7384871ca4","title":"送姜贫乐赴陈华亭约  其一","author":"释居简","dynasty":"宋","verses":["僦屋傍西湖，湖光浸屋除。","秋荷纫雨后，邻米饷斋余。","句熟如圜转，谋生似我疎。","拙吟方巧宦，骚雅费甾畬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-19d13ed2-5cb4-4497-ae17-4ba80e744a03","tags":["西湖"]},{"id":"poem-2cf0405a49bacef30b316aa2","title":"渡江云三犯・渡江云·羞红颦浅恨","author":"吴文英","dynasty":"宋","verses":["羞红颦浅恨，晚风为落，片绣点重茵。","旧堤分燕尾，桂棹轻鸥，宝勒倚残云。","千丝怨碧，渐路入、仙坞迷津。","肠漫回，隔花时见，背面楚腰身。","逡巡。","题门惆怅，堕履牵萦，数幽期难准。","还始觉、留情缘眼，宽带因春。","明朝事与孤烟冷，做满湖、风雨愁人。","山黛暝，尘波澹绿无痕。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-2","tags":["宋词三百首"]},{"id":"poem-2cf1a8b76d8459218daf83bc","title":"题雍丘崔明府丹灶（伯二五六七。下同）","author":"李昂","dynasty":"唐","verses":["闻君小邑𫏐鸣弦，隐几灰心有岁年。","白石既烧应化鹤，黄金未熟且烹鲜。","𬬻中近染三花气，树里新飞五色烟。","伊尹即今须负鼎，王乔何事欲冲天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-061b5fe2-b247-4d80-88fb-c76b48027e5e","tags":[]},{"id":"poem-2cf72c75c5584f9287456443","title":"登甘露寺","author":"周繇","dynasty":"唐","verses":["盘江上几层，峭壁半垂藤。","殿锁南朝像，龛禅外国僧。","海涛摏砌槛，山雨洒窗灯。","日暮疎钟起，声声彻广陵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b5175c34-da87-4de6-b3bc-a935b346fa8e","tags":[]},{"id":"poem-2cfadc52322a6cef64180298","title":"浣溪沙·相见休言有泪珠","author":"欧阳炯","dynasty":"五代","verses":["相见休言有泪珠，酒阑重得叙欢娱，凤屏鸳枕宿金铺。","兰麝细香闻喘息，绮罗纤缕见肌肤，此时还恨薄情无。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-46","tags":[]},{"id":"poem-2cfba556e93697ed5a666e48","title":"题南龛寺  其一","author":"家彬","dynasty":"宋","verses":["岩下楩楠秋复春，当年觞咏悉名臣。","旧游已去成陈迹，佳句还如见古人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-318d0d47-cdb5-4493-b278-f289dd216151","tags":[]},{"id":"poem-2d02fa683e8934e48f2aa3e6","title":"节节高","author":"施惠《幽闺记》","dynasty":"元","verses":["(众)强梁勇猛人会一家，杀人放火张威霸。","行劫掠，聚草粮，屯人马。","惯战武艺多潇洒，从来贼胆天来大，蛟龙猛虎离山窝，闻风那个不惊怕？(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2897","tags":[]},{"id":"poem-2d03d1483625fa3bfe96b057","title":"蓦山溪·凋红减翠","author":"曾觌","dynasty":"宋","verses":["凋红减翠，正是清秋杪。","深院袅香风，看梨花、一枝开早。","珑璁映面，依约认娇颦，天淡淡，月溶溶，春意知多少。","清明池馆，芳信年年好。","更向五侯家，把江梅、风光占了。","休教寂寞，辜负向人心，檀板响，宝杯倾，潘鬓从他老。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-375","tags":[]},{"id":"poem-2d0ccbe7a40fc596a280e603","title":"清人","author":"佚名","dynasty":"先秦","verses":["清人在彭，驷介旁旁。二矛重英，河上乎翱翔。","清人在消，驷介麃麃。二矛重乔，河上乎逍遥。","清人在轴，驷介陶陶。左旋右抽，中军作好。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-78","tags":[]},{"id":"poem-2d12c7ecc4600795ea8c70ca","title":"次分宜","author":"赵文","dynasty":"宋","verses":["分得宜春地，东偏一画屏。","洪阳仙洞古，龙姥故祠灵。","雨过溪痕长，春回草意青。","道傍聊下马，剔藓读碑铭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a13f8ebf-fe5a-4b23-a8fa-5c12267167f1","tags":[]},{"id":"poem-2d1d42b5804ceb2171d2225e","title":"油葫芦","author":"杨景贤","dynasty":"元","verses":["说他几载其间离了大唐，来到俺地方，安排香案快疾忙。","今日取经直过俺金阶上，抵多少醉鞭误入平康巷。","我是一个聪明女，他是一个少年郎。","谁着他不明白抢入我花罗网，准备着金殿锁鸳鸯。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2328","tags":[]},{"id":"poem-2d1d47b791be8a5309d9dccc","title":"咏史诗 召陵","author":"胡曾","dynasty":"唐","verses":["小白匡周入楚郊，楚王雄霸亦咆哮。","不思管仲为谋主，争取言征缩酒茅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c1084295-a1b0-4098-b207-4cab2e1df049","tags":[]},{"id":"poem-2d1dbbf05852e127c9c632b8","title":"和张仆射塞下曲 四","author":"卢纶","dynasty":"唐","verses":["野幕敞琼筵，羌戎贺劳旋。","醉和金甲舞，雷鼓动山川。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9a4d3eae-fe01-46c7-a28b-8b518614a508","tags":["唐诗三百首","乐府","宴饮","边塞","赞颂","将士"]},{"id":"poem-2d1fa16b054570a741a038a3","title":"竹枝歌  其二","author":"孙嵩","dynasty":"宋","verses":["行尽三巴三曲头，一滩自有一生愁。","明朝已过巴陵岸，更宿江陵渔笛洲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0062cb54-de30-4bdc-a90f-65739494473e","tags":[]},{"id":"poem-2d223946b4ca557ec90ecc45","title":"文王有声","author":"佚名","dynasty":"先秦","verses":["文王有声，遹骏有声。遹求厥宁，遹观厥成。文王烝哉！","文王受命，有此武功。既伐于崇，作邑于丰。文王烝哉！","筑城伊淢，作丰伊匹。匪棘其欲，遹追来孝。王后烝哉！","王公伊濯，维丰之垣。四方攸同，王后维翰。王后烝哉！","丰水东注，维禹之绩。四方攸同，皇王维辟。皇王烝哉！","镐京辟雍，自西自东，自南自北，无思不服。皇王烝哉！","考卜维王，宅是镐京。维龟正之，武王成之。武王烝哉！","丰水有芑，武王岂不仕？诒厥孙谋，以燕翼子。武王烝哉！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-243","tags":[]},{"id":"poem-2d2341344c35aca77ca91f13","title":"高阳台·宫粉雕痕","author":"吴文英","dynasty":"宋","verses":["宫粉雕痕，仙云堕影，无人野水荒湾。","古石埋香，金沙锁骨连环。","南楼不恨吹横笛，恨晓风、千里关山。","半飘零，庭上黄昏，月冷阑干。","寿阳空理愁鸾。","问谁调玉髓，暗补香瘢。","细雨归鸿，孤山无限春寒。","离魂难倩招清些，梦缟衣、解佩溪边。","最愁人，啼鸟晴明，叶底青圆。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-79","tags":["宋词三百首"]},{"id":"poem-2d2444aeda5fb5a1c99500fe","title":"经士马中作","author":"贯休","dynasty":"唐","verses":["偷儿成大寇，处处起烟尘。","黄叶满空宅，青山见俗人。","妖星芒刺越，鬼哭势连秦。","惆怅还惆怅，茫茫江海滨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3f216211-6e9e-4ca8-b22f-6309fabbe25c","tags":[]},{"id":"poem-2d2aff7080ab1ab705a10150","title":"题天申宫三首 二","author":"宋维","dynasty":"唐","verses":["中峰嘉树绿阴阴，洞里灵踪已遍寻。","欲下山门又回首，数声清磬白云深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-469d2691-0576-4636-97c3-b1527fb31a6e","tags":[]},{"id":"poem-2d2def792d9798c75f53c032","title":"浣溪沙·雁响遥天玉漏清","author":"顾敻","dynasty":"五代","verses":["雁响遥天玉漏清，小纱窗外月胧明，翠帷金鸭炷香平。","何处不归音信断，良宵空使攀魂惊，簟凉枕冷不胜情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-6","tags":[]},{"id":"poem-2d2f37eac2e4788fcc7fb4d9","title":"戏题诸判官厅壁","author":"包佶","dynasty":"唐","verses":["六十老翁无所取，二三君子不相遗。","愿留今日交欢意，直到隳官谢病时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9b7c07da-1c88-4ce4-8576-fd922f78d183","tags":[]},{"id":"poem-2d2f9a03e8ff49ffd6e526b8","title":"送邢桂州","author":"王维","dynasty":"唐","verses":["铙吹喧京口，风波下洞庭。","赭圻将赤岸，击汰复扬舲。","日落江湖白，潮来天地青。","明珠归合浦，应逐使臣星。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-21a94a4d-4363-406a-8455-45434aa80f7c","tags":["洞庭湖","送别","友情"]},{"id":"poem-2d32723b5a217c7ecac51681","title":"送客往湘江","author":"李端","dynasty":"唐","verses":["识君年已老，孤棹向潇湘。","素发临高镜，清晨入远乡。","三山分夏口，五两映涔阳。","更逐巴东客，南行泪几行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c04af040-9b5f-4954-8080-fc0e5a7feb80","tags":[]},{"id":"poem-2d32848e0e8a59f35e1a8a86","title":"寄广州杨参军","author":"马戴","dynasty":"唐","verses":["南方春景好，念子缓归心。","身方脱野服，冠未系朝簪。","足恣平生赏，无虞外役侵。","汀洲观鸟戏，向月和猨吟。","税驾楚山广，扬帆湘水深。","采奇搜石穴，怀胜即枫林。","怅望极霞际，流情堕海阴。","前朝杳难问，叹息洒鸣琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6179b631-87ba-4a6b-8f1f-a5f5b9b66253","tags":[]},{"id":"poem-2d34e2e4e482fb889aab764b","title":"新节","author":"司空图","dynasty":"唐","verses":["转悲新岁重于山，不似轻鸥肯复还。","朱绂纵教金印换，青云未胜白头闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-237c217b-edba-4bce-964c-d48c994b2188","tags":[]},{"id":"poem-2d3dadfd05e6ef506e017f34","title":"送元结","author":"张籍","dynasty":"唐","verses":["昔日同游漳水边，如今重说恨绵绵。","天涯相见还离别，客路秋风又几年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0d280af5-5168-4daf-9c35-ff414a1c79ad","tags":[]},{"id":"poem-2d4e8fe126e7a728c1edeb6d","title":"三六","author":"王梵志","dynasty":"唐","verses":["饮酒妨生敬，（一本作「计」。","）榻（一本作樗。","）蒲必破家。","但看此等色，不久作穷查。","（本作「茶」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d6046728-b612-4778-925c-95523fc47ae5","tags":[]},{"id":"poem-2d642f2adec22db3fedf979a","title":"句","author":"李涛","dynasty":"宋","verses":["一言寤主宁复听，三谏不从归去来。","谏晋主不从作。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-329ddd62-6d24-4e48-aad7-78a4708b4d6a","tags":[]},{"id":"poem-2d685cd7581c9f7c8473e9c4","title":"横吹曲辞 出塞","author":"耿[𣲗]","dynasty":"唐","verses":["汉家边事重，窦宪出临戎。","绝漠秋山在，阳关旧路通。","列营依茂草，吹角向高风。","更就燕然石，看铭破虏功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-02da7d16-a042-4720-95e6-f4528b25db22","tags":[]},{"id":"poem-2d6cc49b25b9c6473ceeb340","title":"临江仙·万里凉风收积雨","author":"倪偁","dynasty":"宋","verses":["万里凉风收积雨，一天晴碧新开。","暮云归尽绝纤埃。","金波明静夜，玉露湿苍苔。","坐有霜髯诗酒客，平生见月衔杯。","传闻丹诏日边来。","莫辞通夕醉，对景且徘徊。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-448","tags":[]},{"id":"poem-2d72225dd29a9a9eca86cca6","title":"次韵徐秀才十首  其二","author":"陈造","dynasty":"宋","verses":["杜陵将诗坛，受歃凑多士。","黄陈大其传，券契密付委。","徐君万卷腹，诗作风雷起。","春秋富有余，著眼置余子。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b6ea0d33-a3de-43ff-8c18-d8c3a35c3881","tags":[]},{"id":"poem-2d77ac006c339cb19bf07ee4","title":"归雁","author":"钱起","dynasty":"唐","verses":["潇湘何事等闲回，水碧沙明两岸苔。","二十五弦弹夜月，不胜清怨却飞来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-歸雁","tags":[]},{"id":"poem-2d7ee4aed53f6cc55762887d","title":"上元日梦王母献白玉环","author":"张佐","dynasty":"唐","verses":["梦中朝上日，阙下拜天颜。","仿佛瞻王母，分明献玉环。","灵姿趋甲帐，悟道契玄关。","似见霜姿白，如看月彩弯。","霓裳归物外，凤历晓人寰。","仙圣非相远，昭昭寤寐间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a8ad6062-6360-4804-8a85-e123e41c7058","tags":[]},{"id":"poem-2d7f3f8f396eb46b04ad4708","title":"题开元寺牡丹","author":"徐凝","dynasty":"唐","verses":["此花南地知难种，惭愧僧闲用意栽。","海燕解怜频睥睨，胡蜂未识更徘徊。","虚生芍药徒劳妒，羞杀玫瑰不敢开。","惟有数苞红蕚在，含芳只待舍人来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9baec9fe-04ce-4768-a180-4b89e4f877ae","tags":[]},{"id":"poem-2d908fd19915a01030d03d9d","title":"玉楼春·昭华夜醮连清曙","author":"柳永","dynasty":"宋","verses":["昭华夜醮连清曙。","金殿霓旌笼瑞雾。","九枝擎烛灿繁星，百和焚香抽翠缕。","香罗荐地延真驭。","万乘凝旒听秘语。","卜年无用考灵龟，从此乾坤齐历数。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-81","tags":[]},{"id":"poem-2d90d29c4ffdaacc0ec87fc4","title":"荔枝香近・荔枝香·夜来寒侵酒席","author":"周邦彦","dynasty":"宋","verses":["夜来寒侵酒席，露微泫。","舄履初会，香泽方熏，无端暗雨催人，但怪灯偏帘卷。","回顾，始觉惊鸿去云远。","大都世间，最苦唯聚散。","到得春残，看即是、开离宴。","细思别后，柳眼花须更谁剪。","此怀何处消遣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-362","tags":[]},{"id":"poem-2d98a67d417dbf1805e5068b","title":"点绛唇·怯雨羞云","author":"曹勋","dynasty":"宋","verses":["怯雨羞云，翠鬟初按檀槽就。","赏心时候。","常劝花间酒。","慢拈轻拢，怨感随纤手。","胡沙奏。","几行红袖。","都道谁家有。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-201","tags":[]},{"id":"poem-2d9de74504c1d4682e5585ba","title":"瀛岩","author":"高袭明","dynasty":"宋","verses":["温台万丘壑，走遍成重胝。","佳山落床头，咫尺反不知。","我闻野老说，山乃神所移。","蓬莱本三峰，一峰今失之。","上干云霓秀，下压鳌背欹。","夜半见海日，紫晕开咸池。","魑魅看老木，狂鼯向人啼。","危亭无遗栋，绝壁无旧题。","夫子勇我过，竦身敢独跻。","我病不能从，梦寐常追随。","秋风海上来，霜清鲈正肥。","行寻越溪鞅，肃此尘外鞿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2a696096-259e-4215-9475-0657d9e44441","tags":[]},{"id":"poem-2da338773115df63b45e64c7","title":"春秋战国门 王后","author":"周昙","dynasty":"唐","verses":["连环要解解非难，忽碎瑶堦一旦间。","两国相持兵不解，会应俱碎似连环。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b19d41a5-acf2-4cc1-9370-c71ba340b29f","tags":[]},{"id":"poem-2dab1cad228d6f8a6fe35d23","title":"送客归振武","author":"李益","dynasty":"唐","verses":["骏马事轻车，军行万里沙。","胡山通嗢落，汉节绕浑邪。","桂满天西月，芦吹塞北笳。","别离俱报主，路极不为赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2e0cd4ce-4297-420f-a4bf-92e48b38e5d2","tags":[]},{"id":"poem-2db930ed80d9d8b6bb7ae421","title":"游仙词三十三首  其一七","author":"王镃","dynasty":"宋","verses":["夜半瑶宫上会开，龙车声轧凤飞来。","演穷灵宝玄元法，大梵天仙带月回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-370e7dd8-7a41-4423-a8f1-292d727f1cd5","tags":[]},{"id":"poem-2dbb1083178fddf12a690d42","title":"祭汾阴乐章","author":"卢从愿","dynasty":"唐","verses":["坤元载物，阳乐发生。","播植资始，品汇咸亨。","列俎棋布，方坛砥平。","神歆禋祀，后德惟明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f7022466-a984-4926-a64b-be9acb8d8b16","tags":[]},{"id":"poem-2dbbc71f4a5cd052eec8647a","title":"郊庙歌辞 祀雨师乐章 奠币登歌","author":"包佶","dynasty":"唐","verses":["岁正朱明，礼布元制。","惟乐能感，与神合契。","阴雾离翍，灵驭摇裔。","膏泽之庆，期于稔岁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c721f02a-3227-4c0e-8506-8f7aa683399d","tags":[]},{"id":"poem-2dbd24d2d2dc0cfe974c3e10","title":"宿严陵钓台","author":"神颖","dynasty":"唐","verses":["寒谷荒台七里洲，贤人永逐水东流。","独猿叫断青天月，千古冥冥潭树秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-21f3296c-bfbd-471c-bd8b-1b2316ea19e2","tags":[]},{"id":"poem-2dbf18256dc4be6fa563ba64","title":"兰陵王·送春去","author":"刘辰翁","dynasty":"宋","verses":["送春去。","春去人间无路。","秋千外、芳草连天，谁遣风沙暗南浦。","依依甚意绪。","漫忆海门飞絮。","乱鸦过，斗转城荒，不见来时试灯处。","春去。","最谁苦。","但箭雁沉边，梁燕无主。","杜鹃声里长门暮。","想玉树凋土，泪盘如露。","咸阳送客屡回顾。","斜日未能度。","春去。","尚来否。","正江令恨别，庾信愁赋。","苏堤尽日风和雨。","叹神游故国，花记前度。","人生流落，顾孺子，共夜雨。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-89","tags":["宋词三百首"]},{"id":"poem-2dc6b4002422328568a5ace7","title":"禁林春直","author":"李昉","dynasty":"宋","verses":["疏帘摇曳日辉辉，直阁深严半掩扉。","一院有花春昼永，八方无事诏书稀。","树头百啭鶑鶑语，梁上新来燕燕飞。","岂合此身居此地，妨贤尸禄自知非。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-230ffda4-8a59-4f4c-8332-032def25e5ef","tags":[]},{"id":"poem-2dc93c8ef5c186b8b5f8c0b5","title":"忆秦娥·春深浅","author":"纳兰性德","dynasty":"清","verses":["春深浅，一痕摇漾青如剪。","青如剪。","鹭鸶立处，烟芜平远。","吹开吹谢东风倦，缃桃自惜红颜变。","红颜变。","兔葵燕麦，重来相见。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-33","tags":[]},{"id":"poem-2dcc73be45136f439490a172","title":"洞仙歌·月中丹桂","author":"黄庭坚","dynasty":"宋","verses":["月中丹桂，自风霜难老。","阅尽人间盛衰草。","望中秋、才有几日，十分圆，霾风雨，云表常如永昼。","不得文章力，白首防秋，谁念云中上功守。","正注意，得人雄，静扫河山，应难纵、五湖归棹。","问持节冯唐几时来，看再策勋名，印窠如斗。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-654","tags":[]},{"id":"poem-2ddb10cca9f51b2f4734459f","title":"宫词  其二八","author":"张公庠","dynasty":"宋","verses":["影娥池面碧溶溶，荡桨佳人夕照中。","云髻不饶荷叶绿，罗裙未减石榴红。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-49a95ef1-f82f-42f6-9e00-4b2187c42614","tags":[]},{"id":"poem-2de282a32f00a1212107ea02","title":"塞上闻笛","author":"宋济","dynasty":"唐","verses":["雪净遥天牧马还，月明羌笛戍楼闲。","借问梅花何处落，风吹一夜满关山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e4e82f30-de7c-46fa-b0a3-96cdd3b93aab","tags":[]},{"id":"poem-2ded060b6ae4dda5b2b438c9","title":"台州郡治十二诗太守尤延之命赋 霞起堂","author":"林宪","dynasty":"宋","verses":["赤城在何处，明霞坐中起。","大千无色界，向背五云里。","羽人跨丹凤，千载一来止。","咽漱餐泰和，琼田结珠蕊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-96982aaf-4586-424c-bdfa-a74be99cd16c","tags":[]},{"id":"poem-2df29d2893f273813ed3bfbe","title":"王屋山送道士司马承祯还天台","author":"明皇帝","dynasty":"唐","verses":["紫府求贤士，清谿祖逸人。","江湖与城阙，异迹且殊伦。","间有幽栖者，居然厌俗尘。","林泉先得性，芝桂欲调神。","地道逾稽岭，天台接海滨。","音徽从此间，万古一芳春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1f894b7c-19a6-43d2-9f59-2fdc76cf6579","tags":[]},{"id":"poem-2df4155cb87726ab40958773","title":"下第后春日长安寓居三首 二","author":"薛能","dynasty":"唐","verses":["暂屈固何恨，所忧无此时。","隔年空仰望，临日又参差。","劳力且成病，壮心能不衰。","犹将琢磨意，更欲候宗师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9de7e928-d9f7-4162-b7c1-85e47235e2bf","tags":[]},{"id":"poem-2df4f19ad57c1d9c0b691044","title":"王昭君怨诸词人连句","author":"无名氏","dynasty":"唐","verses":["掖庭娇幸在娥眉，争用黄金写艳姿。","始言恩宠由君意，谁谓容颜信画师。","微躯一身入深宫，春华几度落秋风。","君恩不惜便衣处，妾貌应殊画辟中。","间道和亲将我敞，选貌披图遍宫掖。","图中容貌既不如，选后君王空海（望疑「悔」字之误）惜。","始知王意本相亲，自恨舟（望疑「丹」字之误）青每误身。","昔是宫中薄命妾，今成塞外断肠人。","九重恩爱应长谢，万里关山愁远嫁。","飞来北地不胜春，月照南庭空度夜。","夜中含涕独婵娟，遥念君边与朔边。","毳幕不同罗帐日，毡裘非复锦衾年。","长安高阙三千里，一望能令一心死。","秋来怀抱既不堪，况复南飞雁声起。","（此诗见刘复《炖煌掇琐》三四。","题虽标连句，然不著诸词人姓名，故仍以常诗视之。","此诗又见于王重民《〈补全唐诗〉拾遗》。","王辑本刊出于本书成书之后，故两存之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-575dd05d-0c1e-4f1b-8814-a0a1834ba640","tags":[]},{"id":"poem-2df5fba74293216046a155ec","title":"招韩武康章","author":"皎然","dynasty":"唐","verses":["山僧虽不饮，酤酒引陶潜。","此意无人别，多为俗士嫌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1da61721-336f-4f70-9fe4-fc96d8eb9794","tags":[]},{"id":"poem-2e00d14f025644f4f1899d36","title":"梅花","author":"林宪","dynasty":"宋","verses":["野梅空山中，正为照人开。","如何绿窗底，疏映带苍苔。","颇似古君子，无人自不谐。","竹径酒初醒，一信清香来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e24b60ad-6893-4e45-820c-b8c1dda245f0","tags":[]},{"id":"poem-2e1435360d563b2d6b6d596e","title":"句","author":"绍伯","dynasty":"唐","verses":["远声历历风和水，近色青青竹映松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c1b27034-071b-47b8-873c-626933c0b488","tags":[]},{"id":"poem-2e1516dd85d07db1fe230ec2","title":"西池清晖亭","author":"许抗","dynasty":"宋","verses":["亭号清晖阚碧涟，半连村落半神仙。","青山剩得云间日，明月饶分水底天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-62da06e8-39a2-42ed-9be1-c6acb8b51b74","tags":[]},{"id":"poem-2e2a88b50b64736bbe0fead9","title":"送金城公主适西蕃","author":"武平一","dynasty":"唐","verses":["广化三边静，通烟四海安。","还将膝下爱，特副域中欢。","圣念飞玄藻，仙仪下白兰。","日斜征盖没，归骑动鸣鸾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dfd5a06e-6d3b-4a84-8eae-34a157dc7db8","tags":[]},{"id":"poem-2e2aa69f43200093139e0041","title":"寄白二十二舍人","author":"张籍","dynasty":"唐","verses":["早知内诏过先辈，蹭蹬江南百事疎。","湓浦成中为上佐，炉峰寺后著幽居。","偏依仙法多求药，长共僧游不读书。","三省比来名望重，肯容君去乐樵渔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1290d4c7-e30b-4007-a0fe-bac3cb9d0f4f","tags":[]},{"id":"poem-2e2f9ca370c6ef6eabfa6cbd","title":"还家","author":"于邺","dynasty":"唐","verses":["为客忆归舍，归来还寂寥。","壮时看欲过，白首固非遥。","独酌几回醉，此愁终不销。","犹残鸡与犬，驱去住山椒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c167e959-59e2-47cd-bfa5-b7f9eed944b1","tags":[]},{"id":"poem-2e348c0b64fd975d780a4932","title":"浣溪沙·小市东门欲雪天","author":"张泌","dynasty":"五代","verses":["小市东门欲雪天，众中依约见神仙，蕊黄香画贴金蝉。","饮散黄昏人草草，醉容无语立门前，马嘶尘烘一街烟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-36","tags":[]},{"id":"poem-2e38d59a87005203375df203","title":"送况上人还荆州因寄衞侍御象","author":"司空曙","dynasty":"唐","verses":["惠持游蜀久，策杖欲西还。","共别此宵月，独归何处山。","对鸥沙草畔，洗足野云间。","知有玄晖会，斋心受八关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e7ace9a5-8100-4da9-b819-4f45d0f80d0b","tags":[]},{"id":"poem-2e451ea50516999ff29d3ad0","title":"柳杨送客","author":"李益","dynasty":"唐","verses":["青枫江畔白苹洲，楚客伤离不待秋。","君见隋朝更何事，柳杨南渡水悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f07da970-0a2f-4b34-a09f-ff47b6830769","tags":[]},{"id":"poem-2e52fad71dbf5ae11b9d498a","title":"郊庙歌辞 周宗庙乐舞辞 福顺","author":"不详","dynasty":"唐","verses":["新庙奕奕，金奏洋洋。","享于祖考，循彼典章。","清酤特满，嘉玉腾光。","神醉既告，帝祉无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2144751c-5633-4d58-b0bd-5dc2f044b83d","tags":[]},{"id":"poem-2e55bfa293d4462a2ac1cbe0","title":"一斛珠·今朝祖宴","author":"欧阳修","dynasty":"宋","verses":["今朝祖宴。","可怜明夜孤灯馆。","酒醒明月空床满。","翠被重重，不似香肌暖。","愁肠恰似沈香篆。","千回万转萦还断。","梦中若得相寻见。","却愿春宵，一夜如年远。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-786","tags":[]},{"id":"poem-2e5957219c44bd4f41a7da3e","title":"五韵美","author":"施惠《幽闺记》","dynasty":"元","verses":["休戈甲，罢征戍，区宇宣王化，惠及生灵。","恩沾遐迩。","如今日之际，海之涯，普天之下，再生重见太平，欢声四洽。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2995","tags":[]},{"id":"poem-2e6d5966074ca5c93bfad00b","title":"偈 五","author":"契此","dynasty":"唐","verses":["[手]（牛）（从《明州岳林寺志》改）捏青苗种福田，低头便见水中天。","六根清净方成稻，退步（《明州岳林寺志》作「后」）原来是向前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-60634195-17ee-4c1c-948b-b32403ac76a1","tags":[]},{"id":"poem-2e77a128e0c0fbcb0891b6ad","title":"浣溪沙·绿玉丛中紫玉条","author":"向子𬤇","dynasty":"宋","verses":["绿玉丛中紫玉条。","幽花疏淡更香饶。","不将朱粉污高标。","空谷佳人宜结伴，贵游公子不能招。","小窗相对诵离骚。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-124","tags":[]},{"id":"poem-2e7c1a3d1ea674ee12f0959f","title":"除夜","author":"曹松","dynasty":"唐","verses":["残腊即又尽，东风应渐闻。","一宵犹几许，两岁欲平分。","燎暗倾时斗，春通绽处芬。","明朝遥捧酒，先合祝尧君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-13271d26-4e05-4c92-9081-fc65dea31af2","tags":[]},{"id":"poem-2e7fa2702072d6e3f485a969","title":"刮地风","author":"施惠《幽闺记》","dynasty":"元","verses":["(老旦)看他举止，与我孩儿也不甚争。","小娘子，厮跟去，你可心肯？(小旦)奴家不见了哥哥，望老娘带奴同行则个。","(老旦)事既如此，我就把你做女儿看承罢。","(小旦)情愿做小为婢身，焉敢指望做儿称？(老旦)若得干戈宁静，和你同往到神京。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2951","tags":[]},{"id":"poem-2e87b7addae49215e5a551dc","title":"偶登苏州重玄阁","author":"张祜","dynasty":"唐","verses":["飞阁层层茂苑间，夏凉秋晚屙登攀。","万家前后皆临水，四槛高低尽见山。","何事越王侵敌国，不妨辽鹤唁人寰。","五湖直下须归去，自笑身闲迹未闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-cca1a5fb-0c2c-4d93-807d-94bfc7ef1383","tags":[]},{"id":"poem-2e8928d5d8c9890018d1dd7c","title":"侥侥令","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(老旦)这话分明诉与伊，须记得圣贤书。","懊恨娘行忒薄劣，抛闪得两分离在中路里，两分离在中路里。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8273","tags":[]},{"id":"poem-2e8f6c7ad0ae52c870a53f8b","title":"诗品二十四则 含蓄","author":"司空图","dynasty":"唐","verses":["不著一字，尽得风流。","语不涉难，已不堪忧。","是有真宰，与之沈浮。","如渌满酒，花时返秋。","悠悠空尘，忽忽海沤。","浅深聚散，万取一收。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4c871d1f-0985-4ae8-b0d3-9f0ba929a0ec","tags":[]},{"id":"poem-2e95270672f40d936b371a6a","title":"长门怨三首 一","author":"刘皂","dynasty":"唐","verses":["雨滴长门秋夜长，愁心和雨到昭阳。","泪痕不学君恩断，拭却千行更万行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-20696ee7-637c-42bc-8dce-ef4a1dd67b37","tags":[]},{"id":"poem-2e9ebb291d387169f9a88e5d","title":"浣溪沙·欲问江梅瘦几分","author":"纳兰性德","dynasty":"清","verses":["欲问江梅瘦几分，只看愁损翠罗裙。","麝篝衾冷惜余熏。","可耐暮寒长倚竹，便教春好不开门。","枇杷花底校书人。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-19","tags":[]},{"id":"poem-2ea57dc73dd12d26c87f8079","title":"巫山","author":"苏拯","dynasty":"唐","verses":["昔时亦云雨，今时亦云雨。","自是荒淫多，梦得巫山女。","从来圣明君，可听妖魅语。","只今峰上云，徒自生容与。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-93e52142-9415-4dba-bd3f-8822a8d15bf4","tags":[]},{"id":"poem-2eae56dc989d319e11ab0dac","title":"登纠峰顶","author":"吕从庆","dynasty":"唐","verses":["盘盘纠峰岭，不与群峰同。","我来值清秋，落叶飞苍穹。","洪涛湃松柏，烟雨交空蒙。","爱兹竟忘返，非关足力穷。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3b846c76-6ea2-4653-8c27-4f5772a7f594","tags":[]},{"id":"poem-2eb011aa4522abeb9780d6ea","title":"浣溪沙·入夏偏宜淡薄妆","author":"李珣","dynasty":"五代","verses":["入夏偏宜淡薄妆，越罗衣褪郁金黄，翠钿檀注助容光。","相见无言还有恨，几回拚却又思量，月窗香径梦悠飏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-13","tags":[]},{"id":"poem-2eb5689a1f2093deb00d03a7","title":"诗二首  其二","author":"刘望之","dynasty":"宋","verses":["孤舟未晚泊，烟火傍人家。","小市常忧虎，空城不见花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-17ea9e13-671c-429d-bf63-aaabc501075d","tags":[]},{"id":"poem-2eb78e73977cf89871a38f75","title":"酬郑进士九江新居见寄","author":"李咸用","dynasty":"唐","verses":["蹑屐扣柴关，因成尽日闲。","独听黄鸟语，深似白云间。","萍沼宽于井，莎城绿当山。","前期招我作，此景得吟还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-36b816e2-7ec1-4d06-a3bb-fc8f1e1750a7","tags":[]}];
